/*
// FpsUtils3 indev-0.1 currently not functional.
// Written by Saegusa with love<3 and memes
//
// This is a development structral version of
// FpsUtils' new version, which will be the
// third iteration of this mod, which includes
// the same features as before but in a better
// code structure to make it more understandable
// and easier to work on for people other than gooses.
// 
// FpsUtils3 currently includes the new command
// system i thought up for "masterwork" and is beastin
// Pls forward any future requests to my Patreon page:
// https://www.patreon.com/saegusa
//
// Original code repository is placed at:
// https://github.com/Saegusae/fps-utils
*/

let config = require('./config.json');

const format = require('./format'),
      fs = require('fs');

module.exports = function FpsUtils3(dispatch) {

    const CLASSES = config.classes;

    let debug = config.debug || false;

    let player,
        cid,
        model,
        clss;

    let state = config.state || 0,
        lastState = state || 0,
        hiddenPlayers = {},
        hiddenIndividual = {};

    let flags = {
        fireworks: false,
        hide: {
            tanks: false,
            healers: false,
            dps: false
        }
    }

    function getClass(mdl) {
        return (m % 100);
    }

    const commands = {
        state: {
            alias: ["0", "1", "2", "3"],
            help: "Changes fps state to given argument.",
            run: function(args) {

                lastState = state;
                state = parseInt(args[0]);
                config.state = state;

                switch(state) {
                    // State 0: Disable fps-utils optimization.
                    case 0:

                        if(lastState > 2) {
                            // Display all hidden players.
                        }
                        break;
                    // State 1: Hide skill particles and projectiles.
                    case 1:

                        if(lastState > 2) {
                            // Display all hidden players, except individuals.
                        }
                        break;
                    // State 2: Hide skill animations.
                    case 2:

                        if(lastState > 2) {
                            // Display all hidden players, except individuals.
                        }
                        break;
                    // State 3: Hide all players.
                    case 3:

                        if(lastState < 3) {
                            // Hide all players.
                        }
                        break;
                    default:
                        break;
                }
            }
        },
        save: {
            alias: ['save', 'config'],
            help: "Saves current settings to config file for next launch.",
            run: function(args) {
                save((err) => {
                    if(err) {
                        log('Save to config failed.');
                    } else {
                        log('Settings successfully saved to config');
                    }
                });
            }
        },
        fireworks: {
            alias: ['firework', 'fireworks', 'fw'],
            help: "Hide fireworks, and their pesky animations. (true = show | false = hide)",
            run: function(args) {
                flags.fireworks = !flags.fireworks;
                log(`toggled fireworks: ${flags.fireworks}`);
            }
        },
        hide: {
            alias: ['hide', 'h', 'delete'],
            help: "",
            run: function(args) {
                if(args.length < 2) {
                    // Missing argument, throw help function.
                } else {
                    if(state < 3)
                        switch(args[1]) {
                            case "dps":
                            case "healers":
                            case "tanks":

                                // Hide all characters of said class.

                                break;
                            default:

                                // Hide individuals by username.

                                break;
                        }
                }
            }
        },
        show: {
            alias: ['show', 's'],
            help: "",
            run: function(args) {

                if(args.length < 2) {
                    // Missing argument, throw help.
                } else {
                    if(state < 3)
                        switch(args[1]) {
                            case "dps":
                            case "healers":
                            case "tanks":
                                // Show chosen class.
                                break;
                            default:
                                // Show individual by name.
                                break;
                        }
                }

            }
        },
        list: {
            alias: ['list', 'l'],
            help: "Show a list of players hidden by 'hide' command.",
            run: function(args) {
                let hiddenArray = [];
                for(let pl in hiddenIndividual) hiddenArray.push(hiddenIndividual[pl].name);
                log(`Hidden Players: ${hiddenArray}`);
            }
        }
    }

    dispatch.hook('C_CHAT', 1, (event) => {
        if(!event.message.includes('!fps'))
            return;

        let command = format.stripTags(event.message).split(' ');

        if(command.length > 1) {
            command = command.splice(1, 1);
            for(let cmd in commands) {
                if(commands[cmd].alias.indexOf(command[0])) {
                    commands[cmd].run(command);
                }            
            }
        }

        return false;
    });


    function help(cmd) {

    }

    function log(msg) {
        if(debug) console.log('[fps-utils3] ' + msg);
        dispatch.toClient('S_CHAT', 1, {
            channel: 24,
            authorID: 0,
            unk1: 0,
            gm: 0,
            unk2: 0,
            authorName: '',
            message: ' (fps-utils3) ' + msg
        });
    }

    function save(callback) {
        fs.writeFile('./config.json', config, 'utf8', (err) => { 
            if(!err) log("config file overwritten successfully"); 
            else callback(err);
        });
    }

}

// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: deep-gray; icon-glyph: magic;
// Licence: GNU GENERAL PUBLIC LICENSE, Version 3, 29 June 2007
// Author: Marcus Raitner (https://fuehrung-erfahren.de)
// Source: https://github.com/marcusraitner/COVID-19-Dashboard
// ## Changelog
// * 1.0.1: Correction of layout of label for covid-beds
// * 1.0.2: Bug-Fix for Saar-Pfalz-Kreis (using GEN instead of county for join)
// * 1.0.3: Bug-Fix for Landsberg a. Lech (now using both GEN and county)
// * 1.0.4: Bug-Fix. Now using AGS for join (county and GEN only as backup)
// * 1.1.0: New API for vaccinations
// * 1.2.0: New colors and a new step for incidence 165
// * 1.3.0: New feature: Show also incidence for Germany with "showGermanyValue = true"
// * 1.4.0: New feature: R-Value for Germany. Bugfix for date of incidence
// * 1.5.0: Handling of parameters enhanced; see README for full reference
// * 1.6.0: New feature: Use frozen values of RKI
// * 1.7.0: New feature: Show one decimal (optional); improved rounding; minor visual improvements.
// * 1.8.0: Complete redesign of incidence graph and some minor adjustments
// * 1.9.0: Themes and new parameter bl
// * 1.10.0: Added hospitalization
// * 1.10.1: Added toggle for hospitalization
// * 1.10.2: New color in RKI Theme for incidence > 1.000 (and color for 500 adjusted to RKI Dashboard)
// * 1.10.3: Some minor display adjustments
// * 1.11.0: Booster quote
// * 1.12.0: Second Booster quote

const version = "1.12.0"

//------------------------------------------------------------------------------
// General Options Section
//------------------------------------------------------------------------------

// Set to true for debugging information in the console
const debug = false;

// Set to true for an image background, false for no image.
const imageBackground = false;

// Set to true to reset the widget's background image.
const forceImageUpdate = false;

// Show also the incidence for Germany in total
var showGermanyValue = false;

// Show also the R-Value (only if showGermanyValue == true)
var showRValue = true;

// Toggle showing of vaccination status
var showVaccination = true;

// Toggle showing of ICU beds
var showIcu = true;

// show daily portion of incidence
var showDaily = true;

// Show frozen value for incidence instead of calculating it.
var useFrozen = false;

// number of days to show in detail
var detail = 5;

// show values for the state
var showBl = true;

// The color theme
var theme = "original";

// Show Hospitalization
var showHospitalization = false;

// palette found here: https://coolors.co/03071e-370617-6a040f-9d0208-d00000-dc2f02-e85d04-f48c06-faa307-ffba08
const incidenceColors = {
  original: [{
