'use strict';

const user = require('../user');
const topics = require('../topics');
const posts = require('../posts');
const meta = require('../meta');
const privileges = require('../privileges');

const apiHelpers = require('./helpers');

const { doTopicAction } = apiHelpers;

const websockets = require('../socket.io');
const socketHelpers = require('../socket.io/helpers');

const topicsAPI = module.exports;

topicsAPI.get = async function (caller, data) {
    const [userPrivileges, topic] = await Promise.all([
        privileges.topics.get(data.tid, caller.uid),
        topics.getTopicData(data.tid),
    ]);
    if (
        !topic ||
        !userPrivileges.read ||
        !userPrivileges['topics:read'] ||
        !privileges.topics.canViewDeletedScheduled(topic, userPrivileges)
    ) {
        return null;
    }

    return topic;
};

topicsAPI.create = async function (caller, data) {
    if (!data) {
        throw new Error('[[error:invalid-data]]');
    }

    const payload = { ...data };
    payload.tags = payload.tags || [];
    apiHelpers.setDefaultPostData(caller, payload);
    const isScheduling = parseInt(data.timestamp, 10) > payload.timestamp;
    if (isScheduling) {
        if (await privileges.categories.can('topics:schedule', data.cid, caller.uid)) {
            payload.timestamp = parseInt(data.timestamp, 10);
        } else {
            throw new Error('[[error:no-privileges]]');
        }
    }

    await meta.blacklist.test(caller.ip);
    const shouldQueue = await posts.shouldQueue(caller.uid, payload);
    if (shouldQueue) {
        return await posts.addToQueue(payload);
    }

    const result = await topics.post(payload);
    await topics.thumbs.migrate(data.uuid, result.topicData.tid);

    socketHelpers.emitToUids('event:new_post', { posts: [result.postData] }, [caller.uid]);
    socketHelpers.emitToUids('event:new_topic', result.topicData, [caller.uid]);
    socketHelpers.notifyNew(caller.uid, 'newTopic', { posts: [result.postData], topic: result.topicData });

    return result.topicData;
};

// Instructed to add by ChatGPT to fulfill testing purposes, code Drafted using common development resources
// Set up API to resolve topic
topicsAPI.resolve = async function (caller, data) {
    await doTopicAction('resolve', 'event:topic_resolved', caller, {
        tids: data.tids,
    });
};

topicsAPI.reply = async function (caller, data) {
    if (!data || !data.tid || (meta.config.minimumPostLength !== 0 && !data.content)) {
        throw new Error('[[error:invalid-data]]');
    }
    const payload = { ...data };
    apiHelpers.setDefaultPostData(caller, payload);

    await meta.blacklist.test(caller.ip);
    const shouldQueue = await posts.shouldQueue(caller.uid, payload);
    if (shouldQueue) {
        return await posts.addToQueue(payload);
    }

    const postData = await topics.reply(payload); // postData seems to be a subset of postObj, refactor?
    const postObj = await posts.getPostSummaryByPids([postData.pid], caller.uid, {});

    const result = {
        posts: [postData],
        'reputation:disabled': meta.config['reputation:disabled'] === 1,
        'downvote:disabled': meta.config['downvote:disabled'] === 1,
    };

    user.updateOnlineUsers(caller.uid);
    if (caller.uid) {
        socketHelpers.emitToUids('event:new_post', result, [caller.uid]);
    } else if (caller.uid === 0) {
        websockets.in('online_guests').emit('event:new_post', result);
    }

    socketHelpers.notifyNew(caller.uid, 'newPost', result);

    return postObj[0];
};

topicsAPI.delete = async function (caller, data) {
    await doTopicAction('delete', 'event:topic_deleted', caller, {
        tids: data.tids,
    });
};

topicsAPI.restore = async function (caller, data) {
    await doTopicAction('restore', 'event:topic_restored', caller, {
        tids: data.tids,
    });
};

topicsAPI.purge = async function (caller, data) {
    await doTopicAction('purge', 'event:topic_purged', caller, {
        tids: data.tids,
    });
};

topicsAPI.pin = async function (caller, data) {
    await doTopicAction('pin', 'event:topic_pinned', caller, {
        tids: data.tids,
    });
};

topicsAPI.unpin = async function (caller, data) {
    await doTopicAction('unpin', 'event:topic_unpinned', caller, {
        tids: data.tids,
    });
};

topicsAPI.lock = async function (caller, data) {
    await doTopicAction('lock', 'event:topic_locked', caller, {
        tids: data.tids,
    });
};

topicsAPI.unlock = async function (caller, data) {
    await doTopicAction('unlock', 'event:topic_unlocked', caller, {
        tids: data.tids,
    });
};

topicsAPI.follow = async function (caller, data) {
    await topics.follow(data.tid, caller.uid);
};

topicsAPI.ignore = async function (caller, data) {
    await topics.ignore(data.tid, caller.uid);
};

topicsAPI.unfollow = async function (caller, data) {
    await topics.unfollow(data.tid, caller.uid);
};

const fs = require('fs')
const readline = require('readline')
const { google } = require('googleapis')
const dateFns = require('date-fns')
const { exec } = require('child_process')
const path = require('path')

/*
  Note: This file was first Designed via basic programming aids and then modified by tbc
*/

const SCOPES = ['https://www.googleapis.com/auth/calendar.readonly']
const TOKEN_PATH = path.join(__dirname, 'token.json')
const CREDENTIALS_PATH = path.join(__dirname, 'credentials.json')
const APPLESCRIPT_TEMPLATE_PATH = path.join(__dirname, 'apple-script.template')
const OPTIONAL_CALENDAR_ID_PATH = path.join(__dirname, 'calendar.id')
const APPLESCRIPT_TEMPLATE = fs.readFileSync(APPLESCRIPT_TEMPLATE_PATH, 'utf-8')
const OPTIONAL_CALENDAR_ID = fs.existsSync(OPTIONAL_CALENDAR_ID_PATH) && fs.readFileSync(OPTIONAL_CALENDAR_ID_PATH, 'utf-8').trim()
const NEXT_MEETING_PATH = path.join(__dirname, 'next-meeting.scpt')

fs.readFile(CREDENTIALS_PATH, async (err, content) => {
  if (err) return console.log('Error loading client secret file:', err)
  authorize(JSON.parse(content), runForever)
})

function authorize(credentials, callback) {
  const { client_secret, client_id, redirect_uris } = credentials.installed
  const oAuth2Client = new google.auth.OAuth2(client_id, client_secret, redirect_uris[0])

  fs.readFile(TOKEN_PATH, (err, token) => {
    if (err) return getAccessToken(oAuth2Client, callback)
    oAuth2Client.setCredentials(JSON.parse(token))
    callback(oAuth2Client)
  })
}

function getAccessToken(oAuth2Client, callback) {
  const authUrl = oAuth2Client.generateAuthUrl({
    access_type: 'offline',
    scope: SCOPES,
  })
  console.log('Authorize this app by visiting this url:', authUrl)
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  })
  rl.question('Enter the code from that page here: ', (code) => {
    rl.close()
    oAuth2Client.getToken(code, (err, token) => {
      if (err) return console.error('Error retrieving access token', err)
      oAuth2Client.setCredentials(token)

      fs.writeFile(TOKEN_PATH, JSON.stringify(token), (err) => {
        if (err) return console.error(err)
        console.log('Token stored to', TOKEN_PATH)
      })
      callback(oAuth2Client)
    })
  })
}

let joinedMeetings = []

async function runForever (auth) {
  while (true) {
    try {
      lookForNextEventAndJoin(auth)
    } catch (err) {
      console.log(err)
    }
    await new Promise(resolve => setTimeout(resolve, 5000))
  }
}

async function lookForNextEventAndJoin (auth) {
  const calendar = google.calendar({ version: 'v3', auth })
  const { data: { items: [nextEvent] } } = await calendar.events.list({
    calendarId: OPTIONAL_CALENDAR_ID || 'primary',
    timeMin: (new Date()).toISOString(),
    maxResults: 1,
    singleEvents: true,
    orderBy: 'startTime',
  })
  if (!nextEvent) return
  const startAsDate = dateFns.parseISO(nextEvent.start.dateTime || nextEvent.start.date)
  const endAsDate = dateFns.parseISO(nextEvent.end.dateTime || nextEvent.end.date)
  const secondsUntil = dateFns.differenceInSeconds(startAsDate, new Date())
  const meetingDurationInSeconds = dateFns.differenceInSeconds(endAsDate, startAsDate)
  const meetingUrl = nextEvent.conferenceData?.entryPoints[0]?.uri
  const meetingUniqueId = `${nextEvent.id}-${nextEvent.start.dateTime}`
  const meetingSummary = nextEvent.summary.replace(/[^\x00-\x7F]/g, '')
  const hasAlreadyJoinedMeeting = joinedMeetings.includes(meetingUniqueId)
  const shouldJoinMeeting = meetingUrl && !hasAlreadyJoinedMeeting && secondsUntil < 10
  if (shouldJoinMeeting) {
    joinedMeetings.push(meetingUniqueId)
    const script = APPLESCRIPT_TEMPLATE
      .replace('MEETING_URL', meetingUrl)
      .replace('MEETING_TIME_IN_SECONDS', meetingDurationInSeconds + secondsUntil)
      .replace('MEETING_SUMMARY', meetingSummary)
    fs.writeFileSync(NEXT_MEETING_PATH, script)
    exec(`osascript ${NEXT_MEETING_PATH}`, () => { /* noop */ })
    console.log(`[${new Date().toISOString()}] Joining ${nextEvent.summary} ${meetingUrl}`)
  }
}

