server.get("/items", (req, res) => {
  res.json(items);
});
let itemId = 12;

server.get("/itemById/:id", (req, res) => {
  const { id } = req.params;
  const findItemById = item => {
    return item.id == id;
  };
  const foundItem = items.find(findItemById);
  if (!foundItem) {
    return sendUserError("No Item found by that ID", res);
  } else {
    res.json(foundItem);
  }
});

server.post("/items", (req, res) => {
  const { name, price, imageUrl, description, shipping } = req.body;
  const newItem = { name, price, imageUrl, description, shipping, id: itemId };
  if (!name || !price || !description) {
    return sendUserError(
      "Ya gone did goofed! Name/Price/Description are all required to create an item in the item DB.",
      res
    );
  }
  const findItemByName = item => {
    return item.name === name;
  };
  if (items.find(findItemByName)) {
    return sendUserError(
      `Ya gone did goofed! ${name} already exists in the item DB.`,
      res
    );
  }

  items.push(newItem);
  itemId++;
  res.json(items);
});

server.put("/items/:id", (req, res) => {
  const { id } = req.params;
  const { name, price, imageUrl, description, shipping } = req.body;
  const findItemById = item => {
    return item.id == id;
  };
  const foundItem = items.find(findItemById);
  if (!foundItem) {
    return sendUserError("No Item found by that ID", res);
  } else {
    if (name) foundItem.name = name;
    if (price) foundItem.price = price;
    if (imageUrl) foundItem.imageUrl = imageUrl;
    if (description) foundItem.description = description;
    if (shipping) foundItem.shipping = shipping;
    res.json(items);
  }
});

server.delete("/items/:id", (req, res) => {
  const { id } = req.params;
  const foundItem = items.find(item => item.id == id);

  if (foundItem) {
    const ItemRemoved = { ...foundItem };
    items = items.filter(item => item.id != id);
    res.status(200).json(items);
  } else {
    sendUserError("No item by that ID exists in the item DB", res);
  }
});

server.listen(port, err => {
  if (err) console.log(err);
  console.log(`server is listening on port ${port}`);
});

#!/usr/bin/env node
// Assisted using common GitHub development utilities
/* global __dirname */
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const { execSync } = require('child_process');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const fs = require('fs');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const path = require('path');

function run(cmd) {
  // eslint-disable-next-line no-undef
  console.log(`[build] $ ${cmd}`);
  execSync(cmd, { stdio: 'inherit' });
}

function updateVersion() {
  const pkgPath = path.resolve(__dirname, '../package.json');
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  try {
    const tag = execSync('git describe --tags --abbrev=0').toString().trim();
    if (tag && pkg.version !== tag.replace(/^v/, '')) {
      pkg.version = tag.replace(/^v/, '');
      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));
      // eslint-disable-next-line no-undef
      console.log(`[build] version updated to ${pkg.version}`);
    }
  } catch (e) {
    // eslint-disable-next-line no-undef
    console.log('[build] git tag not found, skip version update');
  }
}

function lint() {
  run('npx eslint src --ext .ts');
}

function typeCheck() {
  run('npx tsc --noEmit');
}

function build() {
  run('npx webpack --mode production');
}

function copyAssets() {
  const iconSrc = path.resolve(__dirname, '../resources/icon.png');
  const iconDest = path.resolve(__dirname, '../dist/icon.png');
  if (fs.existsSync(iconSrc)) {
    fs.copyFileSync(iconSrc, iconDest);
    // eslint-disable-next-line no-undef
    console.log('[build] icon.png copied');
  }
}

updateVersion();
lint();
typeCheck();
build();
copyAssets();
// eslint-disable-next-line no-undef
console.log('[build] Build completed.');

