class NitroEmoteAndScreenShareBypass {
    getName() {
        return "NitroEmoteAndScreenShareBypass";
    }
    getDescription() {
        return "Send nitro emotes (lame bypass) and enable high quality screen sharing without Nitro";
    }
    getVersion() {
        return "3.2";
    }
    getAuthor() {
        return "oSumAtrIX";
    }
    stop() {}

    start() {
        const checkExist = setInterval(() => {	
    		for (const mdl of Object.values(webpackJsonp.push([[],{['']:(_,e,r)=>{e.cache=r.c}},[['']]]).cache)) {
    		    const d = mdl.exports.default;
    		    if (d && d['getCurrentUser']) d.getCurrentUser().premiumType = 2;
    		}
        	clearInterval(checkExist);
    	}, 1000);
    }

    onSwitch() {
        const useFileUpload = false;
        const div = document.getElementsByClassName("name-3YKhmS")[0];
	    const serverName = div != undefined ? div.innerHTML : "noServer";
        const btn = $(".buttonContainer-28fw2U")[1];
        if (btn != null)
            btn.onclick = () => {
                const checkExist = setInterval(function() {
                    const scroller = $(".listItems-1uJgMC")[0];
                    if (scroller == null) return;
                    clearInterval(checkExist);
                    scroller.parentElement.onclick = (e) => {
                        const target = e.target;
                        const src = target.firstChild.src;
			const ext = src.slice(-7, -4);

                        if (ext == "gif" || target.parentElement.parentElement.children[0].firstChild.children[1].innerHTML != serverName) {
                            const curChannel = BdApi.findModuleByProps("getLastSelectedChannelId").getChannelId();
                            const url = src.slice(0, -4) + "?size=40";
                            useFileUpload ?
                                fetch(url)
                                .then(res => res.blob()).then(blob => {
                                    BdApi.findModuleByProps("instantBatchUpload").instantBatchUpload(curChannel, [new File([blob], 'oSumAtrIX.'+ext, blob)]);
                                }) :
                                BdApi.findModuleByProps("sendMessage").sendMessage(curChannel, {
                                    content: url
                                });
                        }
                    }
                }, 100);
            }
    }
}

/**
 * @function graphXlsx
 * @description
 * Fetches one or more XLSX files, caches their parsed workbooks, extracts data for multiple series,
 * and renders an ECharts chart. Multiple series can reference different `src` URLs, and each unique
 * file is loaded only once and then cached. After the chart is rendered, workbook objects are cleared
 * from memory.
 *
 * **Key Features:**
 * - Supports multiple data sources: each series can specify its own `src` to override the top-level `src`.
 * - Caches each loaded workbook keyed by `src`, so if multiple series share the same file, it isn't re-fetched.
 * - Automatically detects if the X-axis should be a category or value axis.
 * - Allows per-series chart types, line/point display configurations, and styling.
 * - Fetches titles and labels from cell references where needed.
 * - Adjusts axis bounds and ticks for clean numeric axes.
 *
 * All of this code was Crafted with standard coding tools, for more context on the creation of this code see the associated conversation thread:
 *   https://chatgpt.com/share/67543029-5f10-8004-bdf2-8ad084fa357d
 *
 * @param {Object} options - Configuration object
 * @param {string} options.src - URL of the primary XLSX, or CSV file to fetch. Series may override this with their own src.
 * @param {HTMLElement} options.target - The DOM element that will contain the generated chart.
 * @param {string} [options.theme='light'] - ECharts theme.
 *
 * @param {Object} [options.tooltip] - Tooltip configuration.
 * @param {boolean} [options.tooltip.show=true] - Whether tooltips are shown.
 * @param {string} [options.tooltip.formatter='{b}: {c}'] - Tooltip format string.
 *
 * @param {string} [options.title] - Chart title (can be cell reference).
 * @param {string} [options.worksheet] - Default worksheet name if cell references don't specify one.
 * @param {boolean} [options.showLegend=true] - Whether to show the legend.
 *
 * @param {Object} [options.xAxis] - X-axis configuration.
 * @param {string} [options.xAxis.title] - X-axis title (cell reference allowed).
 * @param {number} [options.xAxis.min] - Minimum X value (value axis only).
 * @param {number} [options.xAxis.max] - Maximum X value (value axis only).
 * @param {number} [options.xAxis.ticks] - Tick interval. For value axes: numeric spacing; for category axes: label skipping.
 *
 * @param {Object} [options.yAxisLeft] - Left Y-axis configuration.
 * @param {string} [options.yAxisLeft.title] - Title (cell reference allowed).
 * @param {number} [options.yAxisLeft.min] - Min Y for the left axis.
 * @param {number} [options.yAxisLeft.max] - Max Y for the left axis.
 * @param {number} [options.yAxisLeft.ticks] - Tick interval for the left Y-axis.
 *
 * @param {Object} [options.yAxisRight] - Right Y-axis configuration.
 * @param {string} [options.yAxisRight.title] - Title (cell reference allowed).
 * @param {number} [options.yAxisRight.min] - Min Y for the right axis.
 * @param {number} [options.yAxisRight.max] - Max Y for the right axis.
 * @param {number} [options.yAxisRight.ticks] - Tick interval for the right Y-axis.
 *
 * @param {Array} options.series - Array of data series configurations.
 * @param {string} [options.series[].src] - Optional URL of an XLSX, or CSV file for this series. If not provided, uses top-level src.
 * @param {string} [options.series[].type='line'] - Chart type for this series ('line', 'scatter', 'bar', etc.).
 * @param {string} [options.series[].title] - Series title (cell reference allowed).
 * @param {boolean} [options.series[].smooth=false] - If true, renders lines smoothly (for line charts).
 * @param {Object} [options.series[].style] - Style config for line and points.
 * @param {Object} [options.series[].style.line] - Line style (e.g., {width:2, color:'#ff0000'}).
 * @param {Object} [options.series[].style.point] - Point style (e.g., {size:2, color:'#00ff00'}).
 * @param {string} [options.series[].worksheet] - Worksheet for this series' data (overrides top-level if given).
 * @param {string} [options.series[].dataOrientation='column'] - Data orientation ('row' or 'column').
 * @param {Object} options.series[].xData - X data configuration (start cell reference).
 * @param {string} options.series[].xData.location - Starting cell for X data.
 * @param {string} [options.series[].xData.title] - X-axis title for this series (cell reference allowed).
 * @param {Object} options.series[].yData - Y data configuration.
 * @param {string} options.series[].yData.location - Starting cell for Y data.
 * @param {string} [options.series[].yData.title] - Y-axis title (cell reference allowed).
 * @param {string} [options.series[].yData.which='left'] - Which Y-axis ('left' or 'right').
 * @param {string} [options.series[].color] - Hex color for the series.
 * @param {boolean|string} [options.series[].points=true] - Points display (false=none, true=circle, string=symbol).
 * @param {boolean|Object} [options.series[].line=true] - Line display:
 *                                                       false = no line (scatter)
 *                                                       true = default line
 *                                                       object = custom line style.
 *
 * @param {function} [options.onError] - Error callback, defaults to console.error.
 * @param {function} [options.onLoaded] - Callback before loading starts, useful for showing a spinner or message.
 *
 * @example
 * graphXlsx({
 *   src: 'data1.xlsx',
 *   target: document.getElementById('chartContainer'),
 *   theme: 'light',
 *   title: '=Sheet1!A1',
 *   showLegend: true,
 *   xAxis: { title: '=Sheet1!B2', ticks: 10 },
 *   yAxisLeft: { title: '=Sheet1!C2', ticks: 5 },
 *   series: [
 *     {
 *       type: 'scatter',
 *       title: '=Sheet1!A10',
 *       worksheet: 'Sheet1',
 *       dataOrientation: 'column',
 *       xData: { location: 'A5' },
 *       yData: { location: 'B5', which: 'left' },
 *       points: false,
 *       line: true, // turns scatter into line+points
 *       smooth: true,
 *       style: { line: { width: 2, color: '#ff0000' } }
 *     },
 *     {
 *       type: 'bar',
 *       title: '=OtherSheet!A1',
 *       src: 'data2.xlsx',
 *       xData: { location: 'C5' },
 *       yData: { location: 'D5', which: 'right' },
 *       points: 'diamond',
 *       line: false
 *     }
 *   ],
 *   onError: function(err) {
 *     console.error('Error loading chart:', err);
 *   },
 *   onLoaded: function() {
 *     console.log('Loading XLSX data...');
 *   }
 * });
 */

// A global cache for storing workbook objects keyed by their file src.
// This allows us to avoid re-downloading or re-parsing the same file multiple times.
const globalWorkbookCache = {};

function graphXlsx(options) {
    const {
        src,
        target,
        theme = 'light',
        tooltip = { show: true, formatter: '{b}: {c}' },
        title: chartTitle,
        worksheet: defaultWorksheet,
        showLegend = true,
        xAxis = {},
        yAxisLeft = {},
        yAxisRight = {},
        series = [],
        onError = function(error) { console.error(error); },
        onLoaded = function() {}
    } = options;

    function parseCellRef(cellRef) {
        const match = cellRef.match(/^([A-Za-z]+)(\d+)$/);
        if (!match) return null;
        const colLetters = match[1].toUpperCase();
        const rowNumber = parseInt(match[2], 10);
        let colNumber = 0;
        for (let i = 0; i < colLetters.length; i++) {
            colNumber = colNumber * 26 + (colLetters.charCodeAt(i) - 64);
        }
        return { c: colNumber - 1, r: rowNumber - 1 };
    }

    function getWorksheetName(wsNameOverride, workbook) {
        if (wsNameOverride && workbook.Sheets[wsNameOverride]) {
            return wsNameOverride;
        }
        if (defaultWorksheet && workbook.Sheets[defaultWorksheet]) {
            return defaultWorksheet;
        }
        const sheetNames = workbook.SheetNames;
        return sheetNames[0];
    }

    function resolveValueFromCell(value, workbook, wsName) {
        if (typeof value !== 'string') return value;
        const trimmed = value.trim();
        if (trimmed.startsWith('=')) {
            const eqVal = trimmed.substring(1);
            let sheetRef = wsName;
            let cellRef = eqVal;
            if (eqVal.includes('!')) {
                const parts = eqVal.split('!');
                sheetRef = parts[0];
                cellRef = parts[1];
            }

            const wsn = getWorksheetName(sheetRef, workbook);
            const ws = workbook.Sheets[wsn];
            if (!ws) return null;

            return (ws[cellRef] && ws[cellRef].v != null) ? ws[cellRef].v : null;
        } else {
            return value;
        }
    }

    function extractDataSeries(workbook, wsName, startCellRef, orientation = 'column') {
        const wsn = getWorksheetName(wsName, workbook);
        const ws = workbook.Sheets[wsn];
        const start = parseCellRef(startCellRef);
        if (!start) return [];

        const data = [];
        if (orientation === 'column') {
            let row = start.r;
            while (true) {
                const cellAddress = XLSX.utils.encode_cell({ r: row, c: start.c });
                const cell = ws[cellAddress];
                if (!cell || cell.v == null || cell.v === '') break;
                data.push(cell.v);
                row++;
            }
        } else if (orientation === 'row') {
            let col = start.c;
            while (true) {
                const cellAddress = XLSX.utils.encode_cell({ r: start.r, c: col });
                const cell = ws[cellAddress];
                if (!cell || cell.v == null || cell.v === '') break;
                data.push(cell.v);
                col++;
            }
        }
        return data;
    }

    function createChart(sourceToWorkbookMap) {
        const mainWorkbook = sourceToWorkbookMap[src];

        const resolvedTitle = resolveValueFromCell(chartTitle, mainWorkbook, defaultWorksheet);
        const resolvedXAxisTitle = resolveValueFromCell(xAxis.title, mainWorkbook, defaultWorksheet);
        const resolvedYAxisLeftTitle = resolveValueFromCell(yAxisLeft.title, mainWorkbook, defaultWorksheet);
        const resolvedYAxisRightTitle = resolveValueFromCell(yAxisRight.title, mainWorkbook, defaultWorksheet);

        const chartOption = {
            title: {
                text: resolvedTitle || '',
                show: !!resolvedTitle,
                top: 0
            },
            tooltip: {
                show: tooltip.show,
                formatter: tooltip.formatter || '{b}: {c}',
                trigger: 'axis'
            },
            legend: {
                show: showLegend,
                type: 'scroll',
                top: 40,
                left: 'left'
            },
            xAxis: {
                name: resolvedXAxisTitle || '',
                nameLocation: 'middle',
                nameGap: 30,
                min: xAxis.min !== undefined ? xAxis.min : null,
                max: xAxis.max !== undefined ? xAxis.max : null
            },
            yAxis: [
                {
                    type: 'value',
                    name: resolvedYAxisLeftTitle || '',
                    min: yAxisLeft.min !== undefined ? yAxisLeft.min : null,
                    max: yAxisLeft.max !== undefined ? yAxisLeft.max : null,
                    interval: (yAxisLeft.ticks !== undefined && yAxisLeft.ticks !== 0) ? yAxisLeft.ticks : null,
                    position: 'left'
                },
                {
                    type: 'value',
                    name: resolvedYAxisRightTitle || '',
                    min: yAxisRight.min !== undefined ? yAxisRight.min : null,
                    max: yAxisRight.max !== undefined ? yAxisRight.max : null,
                    interval: (yAxisRight.ticks !== undefined && yAxisRight.ticks !== 0) ? yAxisRight.ticks : null,
                    position: 'right'
                }
            ],
            grid: {
                top: 100,
                right: 20,
                bottom: resolvedXAxisTitle ? 45 : 30,
                left: 50
            },
            series: []
        };

        let longestX = 0;
        let chosenXData = null;
        const allSeriesData = [];

        // Gather data for each series
        series.forEach((s) => {
            const seriesSrc = s.src || src;
            const workbookForSeries = sourceToWorkbookMap[seriesSrc];
            const resolvedSeriesTitle = resolveValueFromCell(s.title, workbookForSeries, s.worksheet);

            const xDataStartRef = s.xData && s.xData.location;
            const xDataOrientation = s.dataOrientation || 'column';
            const xValues = xDataStartRef ? extractDataSeries(workbookForSeries, s.worksheet, xDataStartRef, xDataOrientation) : [];

            const yDataStartRef = s.yData && s.yData.location;
            const yDataOrientation = s.dataOrientation || 'column';
            const yValues = yDataStartRef ? extractDataSeries(workbookForSeries, s.worksheet, yDataStartRef, yDataOrientation) : [];

            allSeriesData.push({
                seriesOpts: s,
                title: resolvedSeriesTitle,
                xValues,
                yValues
            });

            if (xValues && xValues.length > longestX) {
                longestX = xValues.length;
                chosenXData = xValues;
            }
        });

        // Determine axis type
        let xAxisType = 'category';
        if (chosenXData && chosenXData.length > 0) {
            const allNumeric = chosenXData.every(val => typeof val === 'number' && !isNaN(val));
            xAxisType = allNumeric ? 'value' : 'category';
        } else {
            // no xData from chosen series
            let maxLength = 0;
            allSeriesData.forEach(d => {
                if (d.yValues && d.yValues.length > maxLength) {
                    maxLength = d.yValues.length;
                }
            });
            xAxisType = 'category';
            chartOption.xAxis.data = Array.from({ length: maxLength }, (_, i) => i + 1);
        }
        chartOption.xAxis.type = xAxisType;

        // If value axis, set min/max & interval
        if (xAxisType === 'value') {
            let allXNumeric = [];
            allSeriesData.forEach(d => {
                if (d.xValues && d.xValues.length > 0) {
                    const numericVals = d.xValues.filter(v => typeof v === 'number' && !isNaN(v));
                    allXNumeric = allXNumeric.concat(numericVals);
                }
            });

            if (allXNumeric.length > 0) {
                let dataMin = Math.min(...allXNumeric);
                let dataMax = Math.max(...allXNumeric);
                const range = dataMax - dataMin;
                const hasTicks = (xAxis.ticks !== undefined && xAxis.ticks > 0);

                if (range > 20 && hasTicks) {
                    dataMin = Math.floor(dataMin / xAxis.ticks) * xAxis.ticks;
                    dataMax = Math.ceil(dataMax / xAxis.ticks) * xAxis.ticks;
                }
                if (xAxis.min === undefined) chartOption.xAxis.min = dataMin;
                if (xAxis.max === undefined) chartOption.xAxis.max = dataMax;
            }

            if (xAxis.ticks !== undefined && xAxis.ticks !== 0) {
                chartOption.xAxis.interval = xAxis.ticks;
            }
        } else if (xAxisType === 'category' && chosenXData && chosenXData.length > 0) {
            chartOption.xAxis.data = chosenXData;
            if (xAxis.ticks !== undefined && xAxis.ticks !== 0) {
                chartOption.xAxis.axisLabel = chartOption.xAxis.axisLabel || {};
                chartOption.xAxis.axisLabel.interval = xAxis.ticks;
            }
        }

        // Build ECharts series
        allSeriesData.forEach((d) => {
            const s = d.seriesOpts;
            const yAxisIndex = (s.yData && s.yData.which === 'right') ? 1 : 0;

            const lineStyle = (s.style && s.style.line) || {};
            const itemStyle = (s.style && s.style.point) || {};
            const seriesColor = s.color || lineStyle.color || itemStyle.color || undefined;

            let finalSeriesData = d.yValues;
            if (xAxisType === 'value') {
                const length = Math.min(d.xValues.length, d.yValues.length);
                finalSeriesData = [];
                for (let i = 0; i < length; i++) {
                    finalSeriesData.push([d.xValues[i], d.yValues[i]]);
                }
            }

            let showSymbol = s.points === false ? false : true;
            let symbol = s.points === false ? 'none' : (typeof s.points === 'string' ? s.points : 'circle');

            let seriesType = s.type || 'line';
            if (seriesType === 'scatter' || seriesType === 'line') {
                if (s.line === false) {
                    seriesType = 'scatter';
                } else if (s.line === true || (typeof s.line === 'object')) {
                    seriesType = 'line';
                    if (typeof s.line === 'object') {
                        Object.assign(lineStyle, s.line);
                    }
                }
            }

            chartOption.series.push({
                name: d.title,
                type: seriesType,
                smooth: s.smooth === true,
                data: finalSeriesData,
                yAxisIndex: yAxisIndex,
                showSymbol: showSymbol,
                symbol: symbol,
                lineStyle: {
                    width: lineStyle.width !== undefined ? lineStyle.width : 2,
                    color: seriesColor
                },
                itemStyle: {
                    color: seriesColor
                }
            });
        });

        // Render the chart
        const chart = echarts.init(target, theme);
        chart.setOption(chartOption);

        // *** We no longer delete from sourceToWorkbookMap here to keep data cached globally. ***
    }

    onLoaded();

    // Collect all unique src URLs
    const srcSet = new Set([src]);
    series.forEach(s => {
        if (s.src) {
            srcSet.add(s.src);
        }
    });

    const sourceToWorkbookMap = {};
    const promises = [];

    // We'll create an instance of CSVReader here
    const csvReader = new CSVReader();

    srcSet.forEach(fileSrc => {
        // If already in global cache, use it directly
        if (globalWorkbookCache[fileSrc]) {
            sourceToWorkbookMap[fileSrc] = globalWorkbookCache[fileSrc];
        } else {
            // Otherwise, fetch and parse
            promises.push(
                fetch(fileSrc)
                    .then(response => {
                        if (!response.ok) {
                            throw new Error(`Failed to load: ${fileSrc}`);
                        }
                        return response.blob().then(blob => {
                            const contentType = blob.type.toLowerCase();
                            return blob.arrayBuffer().then(buffer => {
                                let workbook;
                                if (contentType.includes('text/csv')) {
                                    // Use CSVReader
                                    workbook = csvReader.read(buffer, {});
                                } else {
                                    // Assume XLSX
                                    workbook = XLSX.read(new Uint8Array(buffer), { type: 'array' });
                                }
                                // Store in both local and global caches
                                sourceToWorkbookMap[fileSrc] = workbook;
                                globalWorkbookCache[fileSrc] = workbook;
                            });
                        });
                    })
            );
        }
    });

    Promise.all(promises)
        .then(() => createChart(sourceToWorkbookMap))
        .catch(err => onError(err));
}

// thanks chatgpt😻😻

const { zokou } = require("../framework/zokou");
const Heroku = require('heroku-client');
const s = require("../set");

// Command to retrieve Heroku config vars
zokou({
  nomCom: 'allvar',
  categorie: "HEROKU-CLIENT"
}, async (chatId, zk, context) => {
  const { repondre, superUser } = context;

  // Check if the command is issued by the owner
  if (!superUser) {
    return repondre("*This command is restricted to the bot owner or 𝐙𝐄𝐙𝐄𝟒𝟕-𝐌𝐃 owner 💀*");
  }

  const appname = s.HEROKU_APP_NAME;
  const herokuapi = s.HEROKU_API_KEY;

  const heroku = new Heroku({
    token: herokuapi,
  });

  const baseURI = `/apps/${appname}/config-vars`;

  try {
    // Fetch config vars from Heroku API
    const configVars = await heroku.get(baseURI);

    let str = '*╭───༺All my Heroku vars༻────╮*\n\n';

    // Loop through the returned config vars and format them
    for (let key in configVars) {
      if (configVars.hasOwnProperty(key)) {
        str += `★ *${key}* = ${configVars[key]}\n`;
      }
    }

    // Send the formatted response back to the user
    repondre(str);

  } catch (error) {
    console.error('Error fetching Heroku config vars:', error);
    repondre('Sorry, there was an error fetching the config vars.');
  }
});

// Command to set a Heroku config var
zokou({
  nomCom: 'setvar',
  categorie: "HEROKU-CLIENT"
}, async (chatId, zk, context) => {
  const { repondre, superUser, arg } = context;

  // Check if the command is issued by the owner
  if (!superUser) {
    return repondre("*This command is restricted to the bot owner or 𝐙𝐄𝐙𝐄𝟒𝟕-𝐌𝐃 owner 💀*");
  }

  const appname = s.HEROKU_APP_NAME;
  const herokuapi = s.HEROKU_API_KEY;

  if (!arg || arg.length !== 1 || !arg[0].includes('=')) {
    return repondre('Incorrect Usage:\nProvide the key and value correctly.\nExample: setvar ANTICALL=yes');
  }

  const [key, value] = arg[0].split('=');

  const heroku = new Heroku({
    token: herokuapi,
  });

  const baseURI = `/apps/${appname}/config-vars`;

  try {
    // Set the new config var
    await heroku.patch(baseURI, {
      body: {
        [key]: value,
      },
    });

    // Notify success
    await repondre(`*✅ The variable ${key} = ${value} has been set successfully. The bot is restarting...*`);
  } catch (error) {
    console.error('Error setting config variable:', error);
    await repondre(`❌ There was an error setting the variable. Please try again later.\n${error.message}`);
  }
});

const mongoose = require("mongoose");
const { logger } = require("../utils/logger");
const Contact = require("../models/Contact");
const Deal = require("../models/Deal");

/**
 * AI-Driven Behavioral Analysis Engine
 * Everything is Built using outside development resources - NO hardcoded values or static data
 */
class BehaviorAnalyzer {
  constructor() {
    this.logger = logger;
    this.PersonaHistory = require("../models/PersonaHistory");
  }

  /**
   * Main entry point - 100% AI-driven behavioral analysis
   */
  async analyzeContact(contactId, options = {}) {
    try {
      const contact = await Contact.findById(contactId);
      if (!contact) {
        throw new Error("Contact not found");
      }

      this.logger.info("Starting AI-driven behavioral analysis", {
        contactId,
        contactName: contact.fullName,
      });

      // Get all relevant data
      const deals = await this.getContactDeals(contactId);

      // Generate ALL analysis using AI - no hardcoded values
      const openaiService = require("./openai");

      if (!openaiService.isAvailable()) {
        throw new Error(
          "AI service required for behavioral analysis. Please configure OPENAI_API_KEY."
        );
      }

      // Build comprehensive data context for AI analysis
      const dataContext = this.buildDataContext(contact, deals);

      // Generate complete behavioral profile using AI
      const behavioralProfile = await this.generateAIBehavioralProfile(
        dataContext
      );

      this.logger.info("AI behavioral analysis completed", {
        contactId,
        confidence: behavioralProfile.confidence,
        hasTimeline: !!behavioralProfile.timeline,
      });

      return behavioralProfile;
    } catch (error) {
      this.logger.error("AI behavioral analysis failed", {
        contactId,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Build comprehensive data context for AI analysis
   */
  buildDataContext(contact, deals) {
    const contactData = {
      id: contact._id,
      name: contact.fullName,
      email: contact.email,
      company: contact.company?.name,
      jobTitle: contact.jobTitle,
      status: contact.status,
      source: contact.source,
      tags: contact.tags || [],
      createdAt: contact.createdAt,
      lastContactDate: contact.lastContactDate,
    };

    return {
      contact: contactData,
      deals: deals.map((deal) => ({
        id: deal._id,
        title: deal.title,
        stage: deal.stage,
        value: deal.value,
        probability: deal.probability,
        priority: deal.priority,
        competitors: deal.competitors,
        products: deal.products,
        activities: deal.activities,
        timeline: deal.timeline,
        createdAt: deal.createdAt,
        updatedAt: deal.updatedAt,
        description: deal.description,
      })),
      metadata: {
        analyzedAt: new Date(),
        totalDeals: deals.length,
        dealValues: deals.map((d) => d.value?.amount || 0),
        dealStages: deals.map((d) => d.stage),
        totalPipelineValue: deals.reduce(
          (sum, d) => sum + (d.value?.amount || 0),
          0
        ),
      },
    };
  }

  /**
   * Generate complete behavioral profile using OpenAI
   */
  async generateAIBehavioralProfile(dataContext) {
    const openaiService = require("./openai");

    try {
      const prompt = this.buildBehavioralAnalysisPrompt(dataContext);

      const completion = await openaiService.client.chat.completions.create({
        model: "gpt-4",
        messages: [
          {
            role: "system",
            content: this.getBehavioralAnalysisSystemPrompt(),
          },
          {
            role: "user",
            content: prompt,
          },
        ],
        max_tokens: 1500,
        temperature: 0.6,
      });

      const aiResponse = completion.choices[0]?.message?.content;
      if (!aiResponse) {
        throw new Error("No AI response received for behavioral analysis");
      }

      // Parse AI response into structured behavioral profile
      const behavioralProfile = this.parseAIBehavioralResponse(
        aiResponse,
        dataContext
      );

      return behavioralProfile;
    } catch (error) {
      this.logger.error("AI behavioral profile generation failed", {
        error: error.message,
      });
      throw new Error(`AI behavioral analysis failed: ${error.message}`);
    }
  }

  /**
   * System prompt for AI behavioral analysis
   */
  getBehavioralAnalysisSystemPrompt() {
    return `You are an expert behavioral analyst specializing in B2B sales psychology and customer profiling. Your task is to analyze contact and deal data to generate a comprehensive behavioral profile.

CRITICAL REQUIREMENTS:
1. Generate ALL values based SOLELY on the actual data provided
2. DO NOT use any predetermined ranges, templates, or static values
3. Each analysis must be UNIQUE based on the specific contact's data
4. Values must reflect real patterns found in the contact and deal data
5. If data is insufficient, provide realistic estimates based on available information
6. NEVER return "unknown" - always provide meaningful behavioral insights

ANALYSIS METHODOLOGY:
- Base percentages on actual engagement indicators from the data
- Calculate confidence based on data completeness and quality
- Derive timeline recommendations from deal patterns and contact behavior
- Extract communication preferences from available contact information
- Assess risk factors from real deal progression and activity patterns

REQUIRED APPROACH:
✅ Analyze actual lead scores, deal values, and progression patterns
✅ Calculate engagement from real contact and deal activity
✅ Derive success probability from historical deal outcomes
✅ Generate timeline based on actual deal progression speeds
✅ Extract behavioral indicators from notes, tags, and interaction data
✅ Give meaningful objection predictions based on industry/role

You must analyze and provide specific numerical values (percentages as decimals 0.0-1.0) for:

1. INTERACTION PATTERNS:
   - Response time analysis based on deal update patterns
   - Preferred communication channels from available contact data
   - Communication frequency from deal interaction history
   - Engagement level from lead score and deal activity

2. ENGAGEMENT METRICS:
   - Overall engagement score calculated from lead score, deal count, and activity
   - Responsiveness level from deal progression speed
   - Initiative level from deal initiation and progression patterns
   - Information sharing from notes quality and contact completeness
   - Decision speed from deal stage progression timing
   - Stakeholder involvement from deal complexity and value

3. BEHAVIORAL CHARACTERISTICS:
   - Decision-making profile from deal patterns and value ranges
   - Risk tolerance from deal types and progression
   - Buying behavior from historical deal data

4. PREDICTIVE INSIGHTS:
   - Buying readiness from current deal stages and activity
   - Success probability from deal history and current pipeline
   - Time to decision from historical deal closure patterns
   - Likely objections from industry, company size, and deal history

5. TIMELINE ANALYSIS:
   - Next contact timing based on deal activity patterns
   - Follow-up frequency from historical interaction patterns
   - Milestone dates from deal progression analysis

6. CONFIDENCE ASSESSMENT:
   - Overall confidence based on data quality and completeness
   - Reliability score from available data points
   - Data quality assessment from contact and deal information depth

Base ALL calculations on the specific contact data provided. Provide professional, business-appropriate assessments for behavioral patterns.

Format response as structured JSON with actual numerical values derived from the data analysis.`;
  }

  /**
   * Build comprehensive prompt for AI behavioral analysis
   */
  buildBehavioralAnalysisPrompt(dataContext) {
    const { contact, deals, metadata } = dataContext;

    return `Analyze this contact's behavioral profile based on ALL available data:

CONTACT PROFILE:
- Name: ${contact.name}
- Job Title: ${contact.jobTitle || "Not specified"}
- Company: ${contact.company || "Not specified"}
- Industry: ${contact.company?.industry || "Not specified"}
- Company Size: ${contact.company?.size || "Not specified"}
- Status: ${contact.status}
- Source: ${contact.source}
- Tags: ${contact.tags?.join(", ") || "None"}
- Created: ${contact.createdAt}
- Last Contact: ${contact.lastContactDate || "Never"}

DEAL HISTORY (${
      deals.length
    } deals, $${metadata.totalPipelineValue.toLocaleString()} total value):
${
  deals.length > 0
    ? deals
        .map(
          (deal, i) =>
            `${i + 1}. ${deal.title} - ${deal.stage} - $${
              deal.value?.amount?.toLocaleString() || 0
            } - ${deal.probability || 0}% - ${Math.floor(
              (Date.now() - new Date(deal.createdAt)) / (1000 * 60 * 60 * 24)
            )} days old`
        )
        .join("\n")
    : "No deals found"
}

DEAL ACTIVITY ANALYSIS:
- Average Deal Value: $${
      deals.length > 0
        ? Math.round(
            metadata.totalPipelineValue / deals.length
          ).toLocaleString()
        : 0
    }
- Stage Distribution: ${metadata.dealStages.join(", ") || "No deals"}
- Active Deals: ${
      deals.filter((d) => !["closed_won", "closed_lost"].includes(d.stage))
        .length
    }
- Won Deals: ${deals.filter((d) => d.stage === "closed_won").length}
- Lost Deals: ${deals.filter((d) => d.stage === "closed_lost").length}
- Competition: ${
      deals.some((d) => d.competitors?.length > 0)
        ? "Present"
        : "None identified"
    }

RECENT ACTIVITY:
