import { Calibration } from 'reality-mixer';
import { CalibrationWindow, CalibrationWindowHeader } from './calibration-window.js';

const exampleCalibrationJSON = `
{ 
    "schemaVersion": 1, 
    "camera": { 
        "width": 1920, 
        "height": 1080, 
        "fov": 38, 
        "position": [0, 1.5, 0], 
        "orientation": [0, 0, 0, 1] 
    }, 
    "chromaKey": {
        "color": [0, 1, 0],
        "similarity": 0.25,
        "smoothness": 0,
        "crop": [0, 0, 0, 0]
    },
    "delay": 4
}
`

function CalibrationInput(
    onCompleted,
    initialCalibrationJSON = null
) {
    let initialJSON;

    if (initialCalibrationJSON == null) {
        let persistedJSON = localStorage.getItem("calibration-v1");

        if (persistedJSON == null) {
            initialJSON = exampleCalibrationJSON;
        } else {
            initialJSON = persistedJSON;
        }
    } else {
        initialJSON = initialCalibrationJSON;
    }

    let calibrationWindow = CalibrationWindow();

    let header = CalibrationWindowHeader("Calibration Input");

    let titleDiv = document.createElement("div");

    titleDiv.style = "background-color: #50565E; padding: 8px";
    titleDiv.innerText = "Paste or drag and drop your Mixed Reality calibration below:";

    let resultDiv = document.createElement("div");

    resultDiv.style = "padding: 8px; white-space: pre-wrap; background-color: green;";

    let editor = document.createElement("textarea");

    editor.style = `
        font-family: SFMono-Regular, Consolas, "Liberation Mono", Menlo, monospace;
        border: none;
        box-shadow: none;
        outline: none;
        background-color: #303841;
        color: #EFEFEF;
        resize: none;
        margin: 0px;
    `

    editor.rows = 20;
    editor.cols = 80;
    editor.spellcheck = false;
    editor.value = initialJSON;

    function validateCalibration() {
        const maybeJson = editor.value;

        try {
            const json = JSON.parse(maybeJson);
            const calibration = Calibration.fromData(json);

            resultDiv.style.backgroundColor = "green";
            resultDiv.innerHTML = "";

            let link = document.createElement("a");
            link.innerText = "Click here to continue...";
            link.href = "#";
            link.style.color = "#EFEFEF";

            link.onclick = function() {
                localStorage.setItem("calibration-v1", maybeJson);
                onCompleted(calibrationWindow, calibration);
                return false;
            }

            resultDiv.appendChild(link);
        } catch (error) {
            resultDiv.innerText = error;
            resultDiv.style.backgroundColor = "red";
        }
    }

    editor.oninput = validateCalibration;
    validateCalibration();

    calibrationWindow.appendChild(header);
    calibrationWindow.appendChild(titleDiv);
    calibrationWindow.appendChild(editor);
    calibrationWindow.appendChild(resultDiv);

    calibrationWindow.ondrop = function(e) {
        e.preventDefault();

        let file = e.dataTransfer.files[0],
            reader = new FileReader();

        reader.onload = function(event) {
            editor.value = event.target.result;
            validateCalibration();
        };

        reader.readAsText(file);
        return false;
    }

    return calibrationWindow;
}

export { CalibrationInput };

/**
 * cleanUrl
 */

export function cleanUrl(url, { removeQueryParams = false } = {}) {
  if ( typeof url !== 'string' ) return url;

  if ( removeQueryParams ) {
    url = url.split('?')[0];
  }

  return url.toLowerCase().replace(/http?s:\/\//, '').replace(/\/$/, '')
}

/**
 * restoreUrl
 */

export function restoreUrl(url) {
  if ( typeof url !== 'string' ) return url;
  if ( !url.startsWith('http') ) {
    url = `https://${url}`;
  }
  return url;
}

/**
 * getFileSize
 */

export async function getFileSize(url) {
  const data = await fetch(url).then(r => r.blob());
  return data.size;
}

/**
 * addNumbers
 */

export function addNumbers(sizes = []) {
  return sizes.reduce((prev, curr) => prev + curr, 0);
}

/**
 * deduplicateArrayByKey
 * @via Thanks ChatGPT + tweaks
 */

export function deduplicateArrayByKey(arr, key) {
  if ( !Array.isArray(arr) ) return arr;

  const seen = new Set(); // to keep track of seen keys

  return arr.filter((item) => {
    let value = item[key];

    if ( typeof key === 'function' ){
      value = key(item);
    }

    if (seen.has(value)) {
      return false; // skip this item if the key has already been seen
    } else {
      seen.add(value); // mark this key as seen
      return true; // include this item in the filtered array
    }
  });
}

/**
 * isValidUrl
 */

export function isValidUrl(string) {
  try {
    const url = new URL(string);

    if ( !url.host.split('.')[1] ) {
      throw new Error();
    }

    return true;
  } catch(e) {
    return false;
  }
}


/**
 * addCommas
 * @via Thanks ChatGPT
 */

export function addCommas(number) {
  if ( !['string', 'number'].includes(typeof number) ) return number;

  const num = `${number}`;
  const [whole, decimal] = num.split('.');
  let digits = whole.split('');
  let counter = 0;

  // Iterate through the digits from right to left
  for (var i = digits.length - 1; i >= 0; i--) {
    // Increment the counter
    counter++;

    // If the counter is a multiple of 3 and we're not at the leftmost digit, add a comma
    if (counter % 3 === 0 && i !== 0) {
      digits.splice(i, 0, ",");
    }
  }

  digits = digits.join('');

  if ( decimal ) {
    digits = `${digits}.${decimal}`;
  }

  return digits;
}

/**
 * trimString
 */

export function trimString({ string, maxLength, ellipsis = true}) {
  if ( typeof string !== 'string' || string.length <= maxLength ) return string;
  const trimmed = string.split('').slice(0, ellipsis ? maxLength - 3 : maxLength).join('');
  return ellipsis ? `${trimmed}...` : trimmed;
}

/**
 * formatGrams
 */

const defaultFixed = 1;
const maxAutoFixed = 4;

export function formatGrams(grams, { type = 'g', limit, fixed = defaultFixed, commas = true } = {}) {
  let placesToFix = fixed === 'auto' ? defaultFixed : fixed;
  let amount = grams;
  let fixedAmount;

  if ( typeof amount !== 'number' ) return amount;

  if ( limit && amount >= limit ) {
    type = 'kg';
  }

  if ( type === 'kg' ) {
    amount = amount / 1000;
  }

  if ( placesToFix > 0 && amount % 1 !== 0 ) {
    fixedAmount = amount.toFixed(placesToFix)
  } else {
    fixedAmount = `${amount}`;
  }

  const fixedSplit = fixedAmount.split('.');

  if ( fixed === 'auto' && fixedSplit[0] === '0' && fixedSplit[1] ) {
    while ( fixedAmount.split('.')[1].split('').filter(num => num !== '0').length === 0 ) {
      placesToFix = placesToFix + 1;
      fixedAmount = amount.toFixed(placesToFix);
      if ( placesToFix === maxAutoFixed ) break;
    }
  }


  if ( commas ) {
    fixedAmount = addCommas(fixedAmount);
  }

  return `${fixedAmount}${type}`;
}

/**
 * formatBytes
 */

export function formatBytes(grams, { type = 'kb', limit, fixed = 0, commas = true } = {}) {
  let amount = grams;

  if ( typeof amount !== 'number' ) return amount;

  if ( limit && amount >= 1000000 ) {
    type = 'gb'
  } else if ( limit && amount >= limit * 1000 ) {
    type = 'mb';
  } else if ( limit && amount >= limit ) {
    type = 'kb';
  }

  if ( type === 'gb' ) {
    amount = amount / 1000000000;
  } else if ( type === 'mb' ) {
    amount = amount / 1000000;
  } else if ( type === 'kb' ) {
    amount = amount / 1000;
  }

  if ( fixed > 0 && amount % 1 !== 0 ) {
    amount = amount.toFixed(fixed)
  } else if ( fixed === 0 ) {
    amount = Math.ceil(amount);
  }

  if ( commas ) {
    amount = addCommas(amount);
  }

  return `${amount}${type}`;
}

