		spawnAgentgroup: function(troopid,tilepos,team,delta,amount,dir,stance,flag){
			// temp
			troopid = trpid.convert(troopid);
			let pos = tilepos;
			let agentslist = [];
			for (let i = 0; i < amount; i++){ // this one is too slow 
