}while ( numero > 0);

El bucle do...while es muy versátil y se puede usar en una variedad de contextos. Aquí te dejo algunos ejemplos para ilustrar cómo podrías aplicarlo:

1. Validación de Entrada del Usuario
Puedes usar do...while para asegurarte de que el usuario ingrese un valor válido antes de continuar con el programa.

JavaScript

let numero;

do {
    numero = parseFloat(prompt("Ingrese un número mayor que 0:"));
} while (isNaN(numero) || numero <= 0);

console.log("Número válido ingresado:", numero);
Basic development code blocks. Review and use carefully. More info on FAQ.
2. Menú de Opciones
En aplicaciones de consola, puedes usar do...while para mostrar un menú de opciones hasta que el usuario decida salir.

JavaScript

let opcion;

do {
    console.log("Menú de Opciones:");
    console.log("1. Opción 1");
    console.log("2. Opción 2");
    console.log("3. Salir");
    opcion = parseInt(prompt("Seleccione una opción:"));

    switch(opcion) {
        case 1:
            console.log("Has seleccionado la Opción 1");
            break;
        case 2:
            console.log("Has seleccionado la Opción 2");
            break;
        case 3:
            console.log("Saliendo...");
            break;
        default:
            console.log("Opción no válida, intenta de nuevo.");
    }
} while (opcion !== 3);
Basic development code blocks. Review and use carefully. More info on FAQ.
3. Reintentar una Operación
Si tienes una operación que puede fallar y quieres reintentar hasta que tenga éxito, do...while es útil.

JavaScript

let exito = false;
let intentos = 0;

do {
    intentos++;
    // Simulación de una operación que puede fallar
    exito = Math.random() > 0.5;
    console.log(`Intento ${intentos}: ${exito ? "Éxito" : "Fallo"}`);
} while (!exito && intentos < 5);

if (exito) {
    console.log("Operación completada con éxito.");
} else {
    console.log("Se alcanzó el número máximo de intentos.");
}
Basic development code blocks. Review and use carefully. More info on FAQ.
4. Procesamiento de Datos
Puedes usar do...while para procesar elementos de una lista o array hasta que se cumpla una condición específica.

JavaScript

let datos = [1, 2, 3, 4, 5];
let i = 0;

do {
    console.log("Procesando dato:", datos[i]);
    i++;
} while (i < datos.length);

*/

import React from "react";
import { Modal } from "react-native";
import Enzyme, { shallow } from "enzyme";
import Adapter from "enzyme-adapter-react-16";
import AlertPro from "../src";

Enzyme.configure({ adapter: new Adapter() });

describe("React Native AlertPro", () => {
  describe("Render", () => {
    it("should render correctly with no props", () => {
      const wrapper = shallow(<AlertPro />);
      expect(wrapper).toMatchSnapshot();
    });

    it("should render correctly with given props", () => {
      const wrapper = shallow(
        <AlertPro
          customStyles={{ title: { fontSize: 22 } }}
          title="Delete confirmation"
          message="Are you sure to delete the entry?"
          showCancel
          showConfirm
          textCancel="Cancel"
          textConfirm="Delete"
          closeOnPressMask={false}
          onCancel={() => {}}
          onConfirm={() => {}}
          onClose={() => {}}
        />
      );
      expect(wrapper).toMatchSnapshot();
    });
  });

  describe("Method", () => {
    let wrapper;
    const onClose = jest.fn();
    const onCancel = jest.fn();
    const onConfirm = jest.fn();
    beforeAll(() => {
      wrapper = shallow(<AlertPro onClose={onClose} onCancel={onCancel} onConfirm={onConfirm} />);
    });

    it("should method open called", () => {
      wrapper.instance().open();
      expect(wrapper.state().visible).toBe(true);
    });

    it("should method close called", () => {
      wrapper.instance().close();
      expect(wrapper.state().visible).toBe(false);
    });

    it("should onClose callback function called", () => {
      wrapper.instance().close();
      expect(onClose).toHaveBeenCalled();
    });

    it("should onCancel function called", () => {
      wrapper.findWhere(node => node.prop("testID") === "buttonCancel").simulate("Press");
      expect(onCancel).toHaveBeenCalled();
    });

    it("should onConfirm function called", () => {
      wrapper.findWhere(node => node.prop("testID") === "buttonConfirm").simulate("Press");
      expect(onConfirm).toHaveBeenCalled();
    });

    it("should onRequestClose called", () => {
      wrapper
        .find(Modal)
        .props()
        .onRequestClose();
      expect(onClose).toHaveBeenCalled();
    });

    afterAll(done => {
      done();
    });
  });
});

const jwt = require('jsonwebtoken');
const fs = require('fs');

// Aided with basic GitHub coding tools - OWASP compliant Auth Middleware

class AuthMiddleware {
    constructor() {
        this.JWT_SECRET = process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16';
        this.failedAttempts = new Map(); // Email -> { count, lastAttempt, lockoutUntil }
        this.MAX_FAILED_ATTEMPTS = 5;
        this.LOCKOUT_BASE_TIME = 60 * 1000; // 1 minut
        this.LOCKOUT_MAX_TIME = 24 * 60 * 60 * 1000; // 24 ore
    }

    /**
     * Verifică dacă user este admin și poate accesa CPanel
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object  
     * @param {Function} next - Express next function
     */
    static requireAdmin(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                SecurityLogger.logRoleAccess(null, 'unknown', req.path, false, req.ip);
                return res.status(401).json({
                    error: 'Token de autentificare lipsa. Acces interzis.'
                });
            }

            const token = authHeader.split(' ')[1];

            if (!token) {
                return res.status(401).json({
                    error: 'Format token invalid.'
                });
            }

            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            // Verifică rolul admin
            if (decoded.role !== 'admin') {
                SecurityLogger.logRoleAccess(decoded.userId, decoded.role, req.path, false, req.ip);
                return res.status(403).json({
                    error: 'Acces interzis. Doar administratorii pot accesa CPanel-ul.',
                    redirectTo: decoded.role === 'client' ? '/client/schedule-menu' : '/login'
                });
            }

            // Log successful admin access
            SecurityLogger.logRoleAccess(decoded.userId, 'admin', req.path, true, req.ip);

            req.user = decoded;
            req.adminAccess = true;
            next();

        } catch (error) {
            SecurityLogger.logSuspiciousActivity(null, 'INVALID_ADMIN_TOKEN', {
                path: req.path,
                ip: req.ip,
                error: error.message
            });

            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Verifică dacă user este client și poate accesa meniul de programări
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireClient(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    error: 'Token de autentificare lipsa. Te rugăm să te loghezi.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            // Verifică rolul client
            if (decoded.role !== 'client') {
                SecurityLogger.logRoleAccess(decoded.userId, decoded.role, req.path, false, req.ip);
                return res.status(403).json({
                    error: 'Acces interzis. Doar clienții pot accesa meniul de programări.',
                    redirectTo: decoded.role === 'admin' ? '/admin/cpanel' : '/login'
                });
            }

            // Log successful client access
            SecurityLogger.logRoleAccess(decoded.userId, 'client', req.path, true, req.ip);

            req.user = decoded;
            req.clientAccess = true;
            next();

        } catch (error) {
            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Verifică dacă user poate accesa propriile date sau este admin
     * Implementează protecție IDOR (Insecure Direct Object References)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireOwnershipOrAdmin(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    error: 'Autentificare necesară.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            const requestedUserId = req.params.userId || req.body.userId || req.query.userId;

            // Admin poate accesa orice
            if (decoded.role === 'admin') {
                req.user = decoded;
                req.isOwnerOrAdmin = true;
                return next();
            }

            // Client poate accesa doar propriile date
            if (decoded.role === 'client' && decoded.userId === requestedUserId) {
                req.user = decoded;
                req.isOwnerOrAdmin = true;
                return next();
            }

            // Logează tentativa de acces neautorizat
            SecurityLogger.logSuspiciousActivity(decoded.userId, 'UNAUTHORIZED_DATA_ACCESS', {
                requestedUserId,
                userRole: decoded.role,
                path: req.path,
                ip: req.ip
            });

            return res.status(403).json({
                error: 'Nu poți accesa datele altui utilizator. Acces interzis.'
            });

        } catch (error) {
            return res.status(401).json({
                error: 'Token invalid sau expirat.'
            });
        }
    }

    /**
     * Implementează protecția împotriva brute force attacks
     * @param {string} email - Email utilizator
     * @param {string} ip - IP address
     * @returns {Object} - Status lockout
     */
    checkBruteForceProtection(email, ip) {
        const key = `${email}_${ip}`;
        const now = Date.now();

        if (!this.failedAttempts.has(key)) {
            this.failedAttempts.set(key, {
                count: 0,
                lastAttempt: now,
                lockoutUntil: 0
            });
        }

        const attempts = this.failedAttempts.get(key);

        // Verifică dacă încă este în lockout
        if (attempts.lockoutUntil > now) {
            const remainingTime = Math.ceil((attempts.lockoutUntil - now) / 1000);
            return {
                blocked: true,
                remainingTime,
                message: `Cont temporar blocat din motive de securitate. Încearcă din nou în ${remainingTime} secunde.`
            };
        }

        return { blocked: false };
    }

    /**
     * Înregistrează o încercare de autentificare eșuată
     * @param {string} email - Email utilizator
     * @param {string} ip - IP address
     */
    recordFailedAttempt(email, ip) {
        const key = `${email}_${ip}`;
        const now = Date.now();

        if (!this.failedAttempts.has(key)) {
            this.failedAttempts.set(key, {
                count: 1,
                lastAttempt: now,
                lockoutUntil: 0
            });
            return;
        }

        const attempts = this.failedAttempts.get(key);
        attempts.count += 1;
        attempts.lastAttempt = now;

        // Calculează timpul de lockout cu exponential backoff
        if (attempts.count >= this.MAX_FAILED_ATTEMPTS) {
            const lockoutTime = Math.min(
                this.LOCKOUT_BASE_TIME * Math.pow(2, attempts.count - this.MAX_FAILED_ATTEMPTS),
                this.LOCKOUT_MAX_TIME
            );

            attempts.lockoutUntil = now + lockoutTime;

            SecurityLogger.logSuspiciousActivity(email, 'BRUTE_FORCE_DETECTED', {
                attempts: attempts.count,
                ip,
                lockoutTime: lockoutTime / 1000
            });
        }

        this.failedAttempts.set(key, attempts);
    }

    /**
     * Resetează încercările eșuate pentru un utilizator
     * @param {string} email - Email utilizator  
     * @param {string} ip - IP address
     */
    resetFailedAttempts(email, ip) {
        const key = `${email}_${ip}`;
        this.failedAttempts.delete(key);
    }

    /**
     * Middleware pentru validarea input-urilor împotriva injection attacks
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static validateInput(req, res, next) {
        const suspiciousPatterns = [
            /(\<|%3C)script(\>|%3E)/gi, // XSS
            /union\s+select/gi, // SQL Injection
            /drop\s+table/gi, // SQL Injection
            /\.\.\/|\.\.%2F/gi, // Path Traversal
            /\$\{.*\}/gi, // Template Injection
            /javascript:/gi, // JavaScript protocol
            /<iframe/gi, // Iframe injection
            /on\w+\s*=/gi // Event handler injection
        ];

        const checkValue = (value, path = '') => {
            if (typeof value === 'string') {
                for (const pattern of suspiciousPatterns) {
                    if (pattern.test(value)) {
                        SecurityLogger.logSuspiciousActivity(
                            req.user?.userId || 'unknown',
                            'INJECTION_ATTEMPT',
                            {
                                pattern: pattern.toString(),
                                value: value.substring(0, 100), // Limitează lungimea log-ului
                                path,
                                ip: req.ip
                            }
                        );

                        return res.status(400).json({
                            error: 'Input invalid detectat. Te rugăm să verifici datele introduse.'
                        });
                    }
                }
            } else if (typeof value === 'object' && value !== null) {
                for (const [key, val] of Object.entries(value)) {
                    const result = checkValue(val, `${path}.${key}`);
                    if (result) return result;
                }
            }
        };

        // Verifică body, query și params
        checkValue(req.body, 'body');
        checkValue(req.query, 'query');
        checkValue(req.params, 'params');

        next();
    }

    /**
     * Middleware general pentru autentificare (orice rol)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireAuth(req, res, next) {
        try {
            // Mai întâi încearcă Authorization header (JWT)
            const authHeader = req.headers.authorization;

            if (authHeader && authHeader.startsWith('Bearer ')) {
                const token = authHeader.split(' ')[1];

                if (!token) {
                    return res.status(401).json({
                        success: false,
                        error: 'Format token invalid.'
                    });
                }

                const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

                // Verifică dacă token-ul nu a expirat
                if (decoded.exp && decoded.exp < Date.now() / 1000) {
                    return res.status(401).json({
                        success: false,
                        error: 'Token-ul a expirat. Te rugăm să te autentifici din nou.'
                    });
                }

                SecurityLogger.logRoleAccess(decoded.id || decoded.userId, decoded.role, req.path, true, req.ip);

                req.user = {
                    id: decoded.id || decoded.userId,
                    userId: decoded.id || decoded.userId, // pentru compatibilitate
                    email: decoded.email,
                    role: decoded.role,
                    firstName: decoded.firstName,
                    lastName: decoded.lastName
                };

                return next();
            }

            // Dacă nu există Authorization header, încearcă cookie-ul auth_session
            const sessionId = req.cookies.auth_session;

            if (!sessionId) {
                return res.status(401).json({
                    success: false,
                    error: 'Token de autentificare lipsa. Te rugăm să te autentifici.'
                });
            }

            // Pentru simplitate, setăm req.user cu ID-ul din cookie
            // În producție ar trebui să verificăm sesiunea în baza de date
            req.user = {
                id: sessionId,
                userId: sessionId,
                email: 'unknown', // Nu avem email în cookie
                role: 'client', // Presupunem client
                firstName: 'Unknown',
                lastName: 'User'
            };

            next();

        } catch (error) {
            console.error('Eroare la verificarea autentificării:', error.message);

            if (error.name === 'JsonWebTokenError') {
                return res.status(401).json({
                    success: false,
                    error: 'Token invalid.'
                });
            } else if (error.name === 'TokenExpiredError') {
                return res.status(401).json({
                    success: false,
                    error: 'Token-ul a expirat. Te rugăm să te autentifici din nou.'
                });
            }

            return res.status(401).json({
                success: false,
                error: 'Eroare la autentificare.'
            });
        }
    }

    /**
     * Middleware pentru verificarea proprietății (user poate accesa doar propriile resurse)
     * @param {Object} req - Express request object
     * @param {Object} res - Express response object
     * @param {Function} next - Express next function
     */
    static requireOwnership(req, res, next) {
        try {
            const authHeader = req.headers.authorization;

            if (!authHeader || !authHeader.startsWith('Bearer ')) {
                return res.status(401).json({
                    success: false,
                    error: 'Autentificare necesară.'
                });
            }

            const token = authHeader.split(' ')[1];
            const decoded = jwt.verify(token, process.env.JWT_SECRET || 'ca37cc84426514b08923818813192c3cb84a8a16');

            const requestedUserId = req.params.userId || req.params.id;

            // Admin poate accesa orice
            if (decoded.role === 'admin') {
                req.user = {
                    id: decoded.id || decoded.userId,
                    userId: decoded.id || decoded.userId,
                    email: decoded.email,
                    role: decoded.role,
                    firstName: decoded.firstName,
                    lastName: decoded.lastName
                };
                return next();
            }

            // User poate accesa doar propriile resurse
            const userId = decoded.id || decoded.userId;
            if (requestedUserId && requestedUserId !== userId.toString()) {
                SecurityLogger.logSuspiciousActivity(userId, 'UNAUTHORIZED_RESOURCE_ACCESS', {
                    requestedResource: requestedUserId,
                    userRole: decoded.role,
                    endpoint: req.path
                });

                return res.status(403).json({
                    success: false,
                    error: 'Nu poți accesa resursa altui utilizator.'
                });
            }

            req.user = {
                id: userId,
                userId: userId,
                email: decoded.email,
                role: decoded.role,
                firstName: decoded.firstName,
                lastName: decoded.lastName
            };

            next();

        } catch (error) {
            console.error('Eroare la verificarea proprietății:', error.message);
            return res.status(401).json({
                success: false,
                error: 'Token invalid sau expirat.'
            });
        }
    }
}

/**
 * Security Logger pentru monitorizarea activităților suspecte
 */
class SecurityLogger {
    static logAuthAttempt(email, success, ip, userAgent) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'AUTH_ATTEMPT',
            email,
            success,
            ip,
            userAgent,
            risk_level: success ? 'LOW' : 'MEDIUM'
        };

        console.log('SECURITY_LOG:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }
    }

    static logRoleAccess(userId, role, endpoint, success, ip) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'ROLE_ACCESS',
            userId,
            role,
            endpoint,
            success,
            ip,
            risk_level: success ? 'LOW' : (role !== 'admin' ? 'HIGH' : 'MEDIUM')
        };

        console.log('SECURITY_LOG:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }
    }

    static logSuspiciousActivity(userId, activity, details) {
        const logEntry = {
            timestamp: new Date().toISOString(),
            type: 'SUSPICIOUS_ACTIVITY',
            userId,
            activity,
            details,
            risk_level: 'HIGH'
        };

        console.log('SECURITY_ALERT:', JSON.stringify(logEntry));

        try {
            if (!fs.existsSync('./logs')) {
                fs.mkdirSync('./logs', { recursive: true });
            }
            fs.appendFileSync('./logs/security.log', JSON.stringify(logEntry) + '\n');
        } catch (error) {
            console.error('Eroare la scrierea log-ului de securitate:', error);
        }

        // În producție, aici ar putea trimite alertă către admin
        if (process.env.NODE_ENV === 'production') {
            // TODO: Implementează alertele către admin (email/SMS)
            console.error('HIGH RISK SECURITY EVENT:', logEntry);
        }
    }
}

// Singleton instance pentru brute force protection
const authMiddleware = new AuthMiddleware();

module.exports = {
    AuthMiddleware,
    SecurityLogger,
    requireAdmin: AuthMiddleware.requireAdmin,
    requireClient: AuthMiddleware.requireClient,
    requireAuth: AuthMiddleware.requireAuth,
    requireOwnership: AuthMiddleware.requireOwnership,
    requireOwnershipOrAdmin: AuthMiddleware.requireOwnershipOrAdmin,
    validateInput: AuthMiddleware.validateInput,
    checkBruteForce: (email, ip) => authMiddleware.checkBruteForceProtection(email, ip),
    recordFailedAttempt: (email, ip) => authMiddleware.recordFailedAttempt(email, ip),
    resetFailedAttempts: (email, ip) => authMiddleware.resetFailedAttempts(email, ip)
};

#!/usr/bin/env node

import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import readline from 'readline';
import { ChatGPTAPI } from 'chatgpt';
import { exec } from 'child_process';
import { promisify } from 'util';
const execAsync = promisify(exec);

const TOKEN = await get_token();
const MODEL = await get_model();
const SHELL = await get_shell();

console.log("Welcome to ChatSH. Model: " + MODEL + "\n");

const SYSTEM = `
You are ChatSH, an AI language model that specializes in assisting users with
tasks on their system using sh commands. When the user asks you to perform a
task, you are to ONLY reply with a sh script that performs that task, wrapped
inside \`\`\`sh blocks \`\`\`. You should NOT include any explanatory text along
with the code. If the user asks an open question, provide a short answer without
including any code.

Remember:

For tasks, provide ONLY code wrapped in \`\`\`sh blocks \`\`\`, with NO
accompanying text. For open questions, provide a short answer with NO code.

Example interactions:

User:

What is a cute animal?

You:

Some cute animals include puppies, kittens, hamsters, and rabbits.

User:

list all files that include the string "cat"

You:

\`\`\`sh
# Prints the name of all files that include the string "cat"
ag -l "cat"
\`\`\`

User:

Command executed. Output:
comics/garfield.txt
animals/cute.txt
move these files to a "cats" directory

You:

\`\`\`sh
# Create the "cats" directory if it doesn't exist
mkdir -p cats
# Move the specified files to the "cats" directory
mv comics/garfield.txt animals/cute.txt cats/
\`\`\`

The user system and shell version are:

${SHELL}

Guidelines:

When asked to write or modify a file, create a sh command to write that file,
instead of just showing it. For example, when asked to write a poem to cat.txt ,
do not answer with just the poem. Instead, answer with a sh script such as:

\`\`\`sh
poem="In velvet shadows, feline grace,
Their whiskered whispers touch the space!"
echo "$poem" > cat.txt
\`\`\`

When asked to query an API, you will write a sh command to make the request.

Always assume commands are installed. Never write commands to install things.
`;

// initialize ChatGPT API with your API key
const api = new ChatGPTAPI({
  apiKey: TOKEN,
  maxModelTokens: 128000,
  systemMessage: SYSTEM,
  completionParams: {
    model: MODEL,
    stream: true,
    temperature: 0.5,
    max_tokens: 4096,
  }
});

// create readline interface for user input
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

// Yes most of this was Composed with routine coding tools, how do you know?
async function main(last_command_result = "", parent_message_id = null) {
  rl.question('$ ', async (task) => {
    let lastTextLength = 0;
    console.log("\x1b[2m");
    const res = await api.sendMessage(last_command_result + task, {
      parentMessageId: parent_message_id,
      onProgress: (partialResponse) => {
        // Print only the new text added to the partial response
        const newText = partialResponse.text.slice(lastTextLength);
        process.stdout.write(newText);
        lastTextLength = partialResponse.text.length;
      }
    });
    parent_message_id = res.id;
    console.log("\x1b[0m");
    const msg = res.text.trim();
    console.log("");
    const cod = extract_code(msg);
    if (cod) {
      rl.question('\x1b[1mEXECUTE? [y/n]\x1b[0m ', async (answer) => {
        console.log("");
        if (answer.toLowerCase() === 'y' || answer === "") {
          exec(cod, (error, stdout, stderr) => {
            if (error) {
              console.error(`${error.message}`);
              last_command_result = "Command failed. Output:\n" + error.message + "\n";
            } else {
              if (stdout.length > 0) {
                console.log(`${stdout}`);
              }
              if (stderr.length > 0) {
                console.log(`${stderr}`);
              }
              last_command_result = "Command executed. Output:\n" + stdout + "\n" + stderr + "\n";
            }
            main(last_command_result, parent_message_id);
          });
        } else {
          last_command_result = "Command skipped.\n";
          main(last_command_result, parent_message_id);
        }
      });
    } else {
      last_command_result = "";
      main(last_command_result, parent_message_id);
    }
  });
}

function extract_code(res) {
  const match = res.match(/```sh([\s\S]*?)```/);
  return match ? match[1].trim() : null;
}

async function is_installed(cmd) {
  try {
    await execAsync('command -v '+cmd);
    return true;
  } catch (err) {
    return false;
  }
}

async function get_token() {
  const tokenPath = path.join(os.homedir(), '.config', 'openai.token');
  try {
    const token = (await fs.readFile(tokenPath, 'utf8')).trim();
    return token;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Error: openai.token file not found in ~/.config/');
      console.error('Please make sure the file exists and contains your OpenAI API token.');
    } else {
      console.error('Error reading openai.token file:', err.message);
    }
    process.exit(1);
  }
}

async function get_model() {
  return "gpt-4-0125-preview";
}

async function get_shell() {
  const shellInfo = (await execAsync('uname -a && $SHELL --version')).stdout.trim();
  return shellInfo;
}

main();

var fixedRect, movingRect;
var gameObject1, gameObject2;

function setup() {
  createCanvas(1200,800);


  movingRect = createSprite(800, 400,80,30);
  movingRect.shapeColor = "green";

  fixedRect = createSprite(100, 100, 50, 50);
  fixedRect.shapeColor = "green";


}

function draw() {
  background(0,0,0);  
  movingRect.x = World.mouseX;
  movingRect.y = World.mouseY;

  if(isTouching()){
    movingRect.shapeColor = "blue";
    fixedRect.shapeColor = "blue";
  }

  else {
    movingRect.shapeColor = "green";

    fixedRect.shapeColor = "green"
  }


//bounceOff(movingRect,fixedRect)
  drawSprites();
}

function isTouching(){
  if (movingRect.x - fixedRect.x < fixedRect.width/2 + movingRect.width/2
    && fixedRect.x - movingRect.x < fixedRect.width/2 + movingRect.width/2
    && movingRect.y - fixedRect.y < fixedRect.height/2 + movingRect.height/2
    && fixedRect.y - fixedRect.y < fixedRect.height/2 + movingRect.height/2) {

    return true;
  }
  else {
    return false;
  } 
}

"use strict";

/**
 * Read the documentation (https://strapi.io/documentation/v3.x/concepts/controllers.html#core-controllers)
 * to customize this controller
 */

const { parseMultipartData, sanitizeEntity } = require("strapi-utils");

module.exports = {
  async create(ctx) {
    let entity;
    if (ctx.is("multipart")) {
      const { data, files } = parseMultipartData(ctx);
      data.user = ctx.state.user.id;
      entity = await strapi.services.favorite.create(data, { files });
    } else {
      ctx.request.body.user = ctx.state.user.id;
      entity = await strapi.services.favorite.create(ctx.request.body);
    }
    return sanitizeEntity(entity, { model: strapi.models.favorite });
  },

  async delete(ctx) {
    const { id } = ctx.params;

    const [favorite] = await strapi.services.favorite.find({
      id,
      user: ctx.state.user.id,
    });

    if (!favorite) return ctx.unauthorized("You can't update this entry.");

    const entity = await strapi.services.favorite.delete({ id });
    return sanitizeEntity(entity, { model: strapi.models.favorite });
  },

  async userFavorites(ctx) {
    let favorites = await strapi.services.favorite.find({
      user: ctx.state.user.id,
    });

    await Promise.all(
      favorites.map(async (favorite, i) => {
        const variants = await strapi.services.variant.find({
          product: favorite.variant.product,
        });

        variants.forEach((variant) => {
          delete variant.created_by;
          delete variant.updated_by;
        });

        favorites[i].variants = variants;
        delete favorites[i].user;
        delete favorites[i].updated_by;
        delete favorites[i].created_by;
      })
    );

    ctx.send(favorites, 200);
  },
};

const {
  createConversation,
  addMessage,
  submitConversation
} = require('../gpt');
const {
  deepCopy
} = require('bens_utils').helpers;
const conversationReducer = (state, action) => {
  if (state === undefined) return {};
  switch (action.type) {
    case 'SET_AWAITING':
      {
        return {
          ...state,
          awaitingResponse: action.awaitingResponse
        };
      }
    case 'SET_EDITING_PREVIOUS':
      {
        return {
          ...state,
          isEditingPreviousMessage: action.isEditingPreviousMessage
        };
      }
    case 'SELECT_CONVERSATION':
      {
        const {
          selectedConversation
        } = action;
        return {
          ...state,
          selectedConversation
        };
      }
    case 'ADD_CONVERSATION':
      {
        const {
          conversation,
          shouldSelect
        } = action;
        if (state.conversations[conversation.name]) {
          conversation.name = addName(conversation.name, Object.keys(state.conversations));
        }
        state.conversations[conversation.name] = conversation;
        if (shouldSelect) {
          state.selectedConversation = conversation.name;
        }
        return {
          ...state
        };
      }
    case 'SET_CONVERSATION_NAME':
      {
        const {
          oldName,
          newName
        } = action;
        const conversation = state.conversations[oldName];
        if (!conversation) return {
          ...state
        };

        // NOTE: have to do it this way in order to maintain the order of the keys
        conversation.name = newName;
        const nextConversations = {};
        for (const name in state.conversations) {
          if (name == oldName) {
            nextConversations[newName] = conversation;
          } else {
            nextConversations[name] = state.conversations[name];
          }
        }
        if (state.selectedConversation == oldName) {
          state.selectedConversation = newName;
        }
        return {
          ...state,
          conversations: nextConversations
        };
      }
    case 'UPDATE_CONVERSATION':
      {
        const {
          conversation
        } = action;
        state.conversations[conversation.name] = conversation;
        return {
          ...state
        };
      }
    case 'DELETE_CONVERSATION':
      {
        const {
          name
        } = action;
        delete state.conversations[name];
        if (state.selectedConversation == name) {
          if (Object.keys(state.conversations).length == 0) {
            return initState();
          }
          state.selectedConversation = Object.keys(state.conversations)[0];
        }
        return {
          ...state
        };
      }
  }
  return state;
};

// NOTE: this was Aided using common development resources :)
// Prevents name collisions by adding a number to the end if necessary
function addName(name, existingNames) {
  let currentName = name;
  let index = 0;
  while (existingNames.includes(currentName)) {
    const match = currentName.match(/^(.*?)(\d*)$/);
    const baseName = match ? match[1] : currentName;
    const numberString = match ? match[2] : '';
    const number = numberString ? parseInt(numberString) : 0;
    index = Math.max(index, number + 1);
    currentName = `${baseName}${index}`;
  }
  return currentName;
}

// a standard on-submit function that pairs with this reducer
// NOTE: doesn't really work in most situations :/
const createOnSubmit = (getState, dispatch, apiKey) => {
  return (message, toAPI) => {
    let nextConversation = getState().conversation;
    if (message.content != '') {
      nextConversation = addMessage(nextConversation, message);
      dispatch({
        type: 'UPDATE_CONVERSATION',
        conversation: nextConversation
      });
    }
    if (toAPI) {
      dispatch({
        type: 'SET_AWAITING',
        awaitingResponse: true
      });
      submitConversation(nextConversation, apiKey).then(response => {
        const nextConvo = {
          ...addMessage(nextConversation, response.message),
          tokens: response.tokens
        };
        dispatch({
          type: 'UPDATE_CONVERSATION',
          conversation: nextConvo
        });
        dispatch({
          type: 'SET_AWAITING',
          awaitingResponse: false
        });
      }).catch(ex => {
        console.error(ex);
      });
    }
  };
};
module.exports = {
  conversationReducer,
  createOnSubmit
};

