'use strict'; // code generated by pbf v3.1.0

// PlaybackPacket ========================================

var PlaybackPacket = exports.PlaybackPacket = {};

PlaybackPacket.read = function (pbf, end) {
    return pbf.readFields(PlaybackPacket._readField, {session_id: 0, channel_id: 0, timestamp_delta: 0, payload: null}, end);
};
PlaybackPacket._readField = function (tag, obj, pbf) {
    if (tag === 1) obj.session_id = pbf.readVarint();
    else if (tag === 2) obj.channel_id = pbf.readVarint();
    else if (tag === 3) obj.timestamp_delta = pbf.readSVarint();
    else if (tag === 4) obj.payload = pbf.readBytes();
};
PlaybackPacket.write = function (obj, pbf) {
    if (obj.session_id) pbf.writeVarintField(1, obj.session_id);
    if (obj.channel_id) pbf.writeVarintField(2, obj.channel_id);
    if (obj.timestamp_delta) pbf.writeSVarintField(3, obj.timestamp_delta);
    if (obj.payload) pbf.writeBytesField(4, obj.payload);
};

function checkByList(input, bad_words) {
    for (var i = 0; i < bad_words.length; i++) {
        // Number 1 can be interpreted as l or I.
        var sanitizedBadWord = bad_words[i].replace('l', 'i')
        if (new RegExp(sanitizedBadWord, "gi").test(input)) return true;
    }
    return false;
}

var hasProfanityFactory = function () {
    var list = [].slice.call(arguments);
    if (list.length == 0 || typeof list[0] === 'string') {
        console.warn("No locales were added to nanoid-good. Maybe you forgot to add `require('nanoid-good/locale/en')`?")
        return false;
    }
    return function (input) {
        var inputWithNumbersReplaced = input
            .replace('1', 'i')
            .replace('3', 'e')
            .replace('5', 's')
            .replace('8', 'b')
            .replace('0', 'o')

        for (var i = 0; i < list.length; i++) {
            if (checkByList(inputWithNumbersReplaced, list[i])) return true;
        }
        return false;
    };
};

module.exports = hasProfanityFactory;

