import { useState, useEffect } from 'react';
import axios from './api/axiosConfig';
import { useParams } from 'react-router-dom';

// This code is mostly Produced via common programming aids4 or with help from GPT4
function SessionDetails() {
  const { id } = useParams();
  const [session, setSession] = useState(null);
  const [numSeats, setNumSeats] = useState(1);
  const [recommendedSeats, setRecommendedSeats] = useState([]);

  useEffect(() => {
    axios.get(`/sessions/${id}`)
      .then(response => {
        setSession(response.data);
      })
      .catch(error => {
        console.error('Error fetching session', error);
      });
  }, [id]);

  if (!session) {
    return <div>Loading...</div>;
  }

  const handleSeatRequest = () => {
    console.log(id)
    console.log(numSeats)
    axios.get(`/sessions/${id}/recommend-seats?numSeats=${numSeats}`)
      .then(response => {
        console.log(response.data);
        const leftMostSeat = { row: response.data[0] + 1, column: response.data[1] + 1 };
        const newRecommendedSeats = Array.from({length: numSeats}, (_, i) => ({ row: leftMostSeat.row, column: leftMostSeat.column + i }));
        setRecommendedSeats(newRecommendedSeats);
        console.log(newRecommendedSeats);
      })
      .catch(error => {
        console.error('Error fetching recommended seats', error);
      });
  };

  const handleWatch = () => {
    axios.post('/films/watch', session.film)
        .then(response => {
            console.log('Film added to watch history', response);
        })
        .catch(error => {
            console.error('Error adding film to watch history', error);
        });
  };

  return (
    <div>
      <h2>{session.film.title}</h2>
      <p>{new Date(session.time).toLocaleString()}</p>
      <p>{session.language}</p>
      <input type="number" min="1" value={numSeats} onChange={e => setNumSeats(e.target.value)} />
      <button onClick={handleSeatRequest}>Find Seats</button>
      <button onClick={handleWatch}>Watch</button>
      <div>
        {session.isSeatFree.map((row, i) => (
          <div key={i}>
            {row.map((seat, j) => {
                const isRecommended = recommendedSeats.some(s => s.row === i+1 && s.column === j+1);
                return (
                    <span key={j} style={{backgroundColor: isRecommended ? 'yellow' : 'white'}}>
                    {seat ? '🟩' : '🟥'}
                    </span>
                );
                })}
          </div>
        ))}
      </div>
    </div>
  );
}

export default SessionDetails;

#!/usr/bin/env node

// Supported via standard GitHub programming aids
// Web server for PrismWeave web deployment
// Serves built web files with proper MIME types and CORS headers

const http = require('http');
const fs = require('fs');
const path = require('path');
const url = require('url');

class PrismWeaveWebServer {
  constructor(options = {}) {
    this.port = options.port || 8080;
    this.host = options.host || 'localhost';
    this.distPath = path.join(__dirname, 'dist', 'web');
    this.watch = options.watch || false;
    this.debounceMs = options.debounceMs || 500;
    this._watcher = null;
    this._rebuildTimer = null;
    this._isBuilding = false;
    this.mimeTypes = {
      '.html': 'text/html',
      '.js': 'application/javascript',
      '.css': 'text/css',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.gif': 'image/gif',
      '.svg': 'image/svg+xml',
      '.ico': 'image/x-icon',
      '.woff': 'font/woff',
      '.woff2': 'font/woff2',
      '.ttf': 'font/ttf',
      '.eot': 'application/vnd.ms-fontobject',
    };
  }

  start() {
    // Check if web files exist
    if (!fs.existsSync(this.distPath)) {
      console.error('❌ Web distribution not found. Run "npm run build:web" first.');
      process.exit(1);
    }

    const server = http.createServer((req, res) => {
      this.handleRequest(req, res);
    });

    server.listen(this.port, this.host, () => {
      console.log(`🌐 PrismWeave Web Server started`);
      console.log(`📍 Website root: http://${this.host}:${this.port}/`);
      console.log(`📁 Serving directory: ${this.distPath}`);
      console.log(`🔗 Bookmarklet Generator: http://${this.host}:${this.port}/`);
      if (this.watch) {
        console.log('👀 Watch mode enabled (will rebuild on changes)');
        this.startWatching();
      }
      console.log('Press Ctrl+C to stop the server');
    });

    // Graceful shutdown
    process.on('SIGINT', () => {
      console.log('\n🛑 Shutting down server...');
      server.close(() => {
        console.log('✅ Server stopped');
        process.exit(0);
      });
    });
  }

  startWatching() {
    const websiteSrc = path.join(__dirname, 'website');
    const extensionDist = path.join(__dirname, 'dist', 'browser-extension');
    const bookmarkletDist = path.join(__dirname, 'dist', 'bookmarklet');

    const watchTargets = [websiteSrc];
    // Only watch extension/bookmarklet outputs if they exist, so quick iterations on website are fast
    if (fs.existsSync(extensionDist)) watchTargets.push(extensionDist);
    if (fs.existsSync(bookmarkletDist)) watchTargets.push(bookmarkletDist);

    console.log('🔍 Watching paths for changes:', watchTargets.map(p => path.relative(__dirname, p)).join(', '));

    const rebuild = () => {
      if (this._isBuilding) return; // skip if build in progress
      this._isBuilding = true;
      const started = Date.now();
      process.stdout.write('♻️  Rebuilding web assets... ');
      try {
        // Synchronously invoke build.js web
        const { execSync } = require('child_process');
        execSync('node build.js web', { cwd: __dirname, stdio: 'ignore' });
        const duration = Date.now() - started;
        console.log(`done (${duration}ms)`);
      } catch (err) {
        console.error('\n❌ Rebuild failed:', err.message);
      } finally {
        this._isBuilding = false;
      }
    };

    this._watcher = watchTargets.map(target =>
      fs.watch(target, { recursive: true }, (eventType, filename) => {
        if (!filename) return;
        // Ignore temp files or coverage artifacts
        if (/\.swp$|~$|\.tmp$/i.test(filename)) return;
        if (this._rebuildTimer) clearTimeout(this._rebuildTimer);
        this._rebuildTimer = setTimeout(rebuild, this.debounceMs);
      })
    );
  }

  handleRequest(req, res) {
    const parsedUrl = url.parse(req.url);
    let pathname = parsedUrl.pathname;

    // Quiet noisy dev tooling: ignore socket.io/ws polling paths (no HMR server here)
    if (pathname && (pathname.startsWith('/ws/') || pathname.startsWith('/socket.io'))) {
      this.sendNoop(res);
      return;
    }

    // Default to index.html for root requests
    if (pathname === '/') {
      pathname = '/index.html';
    }

    // Security: prevent directory traversal
    pathname = pathname.replace(/\.\./g, '');

    const filePath = path.join(this.distPath, pathname);
    const extname = path.extname(filePath).toLowerCase();

    // Check if file exists
    fs.access(filePath, fs.constants.F_OK, (err) => {
      if (err) {
        this.send404(res, pathname);
        return;
      }

      // Check if it's a directory
      fs.stat(filePath, (err, stats) => {
        if (err) {
          this.send500(res, err);
          return;
        }

        if (stats.isDirectory()) {
          // Try to serve index.html from directory
          const indexPath = path.join(filePath, 'index.html');
          fs.access(indexPath, fs.constants.F_OK, (err) => {
            if (err) {
              this.sendDirectoryListing(res, filePath, pathname);
            } else {
              this.serveFile(res, indexPath, '.html');
            }
          });
        } else {
          this.serveFile(res, filePath, extname);
        }
      });
    });
  }

  serveFile(res, filePath, extname) {
    const contentType = this.mimeTypes[extname] || 'application/octet-stream';

    fs.readFile(filePath, (err, content) => {
      if (err) {
        this.send500(res, err);
        return;
      }

      // Set CORS headers for development
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
      res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

      // Set cache headers
      if (extname === '.js' || extname === '.css') {
        res.setHeader('Cache-Control', 'public, max-age=3600'); // 1 hour for assets
      } else {
        res.setHeader('Cache-Control', 'public, max-age=300'); // 5 minutes for content
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content, 'utf-8');

      console.log(`📄 ${new Date().toISOString()} - ${filePath.replace(this.distPath, '')}`);
    });
  }

  sendDirectoryListing(res, dirPath, urlPath) {
    fs.readdir(dirPath, (err, files) => {
      if (err) {
        this.send500(res, err);
        return;
      }

      const listing = files.map(file => {
        const filePath = path.join(dirPath, file);
        const stats = fs.statSync(filePath);
        const isDir = stats.isDirectory();
        const url = path.join(urlPath, file).replace(/\\/g, '/');

        return {
          name: file + (isDir ? '/' : ''),
          url: url + (isDir ? '/' : ''),
          isDirectory: isDir,
          size: isDir ? '-' : this.formatFileSize(stats.size),
          modified: stats.mtime.toISOString(),
        };
      });

      const html = this.generateDirectoryHTML(urlPath, listing);

      res.setHeader('Access-Control-Allow-Origin', '*');
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(html);

      console.log(`📁 ${new Date().toISOString()} - Directory listing: ${urlPath}`);
    });
  }

  generateDirectoryHTML(dirPath, files) {
    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Directory: ${dirPath}</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; margin: 40px; }
        h1 { color: #2563eb; border-bottom: 2px solid #e5e7eb; padding-bottom: 10px; }
        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
        th, td { text-align: left; padding: 12px; border-bottom: 1px solid #e5e7eb; }
        th { background: #f8fafc; font-weight: 600; }
        a { color: #2563eb; text-decoration: none; }
        a:hover { text-decoration: underline; }
        .directory { font-weight: 600; }
        .size { text-align: right; font-family: monospace; }
        .date { font-family: monospace; font-size: 0.9em; color: #6b7280; }
        .back { margin: 20px 0; }
        .back a { background: #f3f4f6; padding: 8px 16px; border-radius: 6px; }
    </style>
</head>
<body>
    <h1>📁 Directory: ${dirPath}</h1>

    ${dirPath !== '/' ? '<div class="back"><a href="../">← Back</a></div>' : ''}

    <table>
        <thead>
            <tr>
                <th>Name</th>
                <th>Size</th>
                <th>Modified</th>
            </tr>
        </thead>
        <tbody>
            ${files.map(file => `
                <tr>
                    <td>
                        <a href="${file.url}" class="${file.isDirectory ? 'directory' : ''}">
                            ${file.isDirectory ? '📁' : '📄'} ${file.name}
                        </a>
                    </td>
                    <td class="size">${file.size}</td>
                    <td class="date">${new Date(file.modified).toLocaleString()}</td>
                </tr>
            `).join('')}
        </tbody>
    </table>

    <div style="margin-top: 40px; padding: 20px; background: #f8fafc; border-radius: 8px;">
        <h3>🚀 PrismWeave Web Server</h3>
        <p>Serving files from: <code>${this.distPath}</code></p>
        <p>Server time: ${new Date().toISOString()}</p>
    </div>
</body>
</html>`;
  }

  send404(res, pathname) {
    const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>404 Not Found</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; 
               text-align: center; margin: 0; padding: 60px 20px; background: #f8fafc; }
        .container { max-width: 600px; margin: 0 auto; background: white; 
                    padding: 40px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        h1 { color: #dc2626; font-size: 4rem; margin-bottom: 20px; }
        h2 { color: #374151; margin-bottom: 20px; }
        p { color: #6b7280; margin-bottom: 30px; }
        a { color: #2563eb; text-decoration: none; padding: 12px 24px; 
            background: #eff6ff; border-radius: 6px; display: inline-block; }
        a:hover { background: #dbeafe; }
    </style>
</head>
<body>
    <div class="container">
        <h1>404</h1>
        <h2>Page Not Found</h2>
        <p>The requested file <code>${pathname}</code> was not found.</p>
        <a href="/">← Back to Home</a>
    </div>
</body>
</html>`;

    res.setHeader('Access-Control-Allow-Origin', '*');
    res.writeHead(404, { 'Content-Type': 'text/html' });
    res.end(html);

    console.log(`❌ ${new Date().toISOString()} - 404: ${pathname}`);
  }

  send500(res, error) {
    const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>500 Server Error</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; 
               text-align: center; margin: 0; padding: 60px 20px; background: #fef2f2; }
        .container { max-width: 600px; margin: 0 auto; background: white; 
                    padding: 40px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        h1 { color: #dc2626; font-size: 4rem; margin-bottom: 20px; }
        h2 { color: #374151; margin-bottom: 20px; }
        p { color: #6b7280; margin-bottom: 30px; }
        .error { background: #fef2f2; padding: 20px; border-radius: 6px; 
                 border-left: 4px solid #dc2626; text-align: left; margin: 20px 0; }
        a { color: #2563eb; text-decoration: none; padding: 12px 24px; 
            background: #eff6ff; border-radius: 6px; display: inline-block; }
        a:hover { background: #dbeafe; }
    </style>
</head>
<body>
    <div class="container">
        <h1>500</h1>
        <h2>Server Error</h2>
        <p>An internal server error occurred while processing your request.</p>
        <div class="error">
            <strong>Error:</strong> ${error.message}
        </div>
        <a href="/">← Back to Home</a>
    </div>
</body>
</html>`;

    res.setHeader('Access-Control-Allow-Origin', '*');
    res.writeHead(500, { 'Content-Type': 'text/html' });
    res.end(html);

    console.error(`💥 ${new Date().toISOString()} - 500: ${error.message}`);
  }

  // Return 204 No Content for known dev-tool polling endpoints
  sendNoop(res) {
    try {
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.writeHead(204);
      res.end();
    } catch (e) {
      // Best-effort noop
      try {
        res.end();
      } catch (_) {}
    }
  }

  formatFileSize(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  }
}

// Parse command line arguments
function parseArgs() {
  const args = process.argv.slice(2);
  const options = {};

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--port' || arg === '-p') {
      options.port = parseInt(args[++i]) || 8080;
    } else if (arg === '--host' || arg === '-h') {
      options.host = args[++i] || 'localhost';
    } else if (arg === '--watch' || arg === '-w') {
      options.watch = true;
    } else if (arg === '--debounce') {
      options.debounceMs = parseInt(args[++i]) || 500;
    } else if (arg === '--help') {
      console.log(`
PrismWeave Web Server

Usage: node serve-web.js [options]

Options:
  -p, --port <port>    Port to listen on (default: 8080)
  -h, --host <host>    Host to bind to (default: localhost)
  -w, --watch          Rebuild web bundle on changes (website/, dist/browser-extension, dist/bookmarklet)
  --debounce <ms>      Debounce interval for rebuilds (default: 500)
  --help               Show this help message

Examples:
  node serve-web.js
  node serve-web.js --port 3000
  node serve-web.js --host 0.0.0.0 --port 8080
  node serve-web.js --watch --debounce 300
      `);
      process.exit(0);
    }
  }

  return options;
}

// Main execution
if (require.main === module) {
  const options = parseArgs();
  const server = new PrismWeaveWebServer(options);
  server.start();
}

module.exports = { PrismWeaveWebServer };

require('dotenv').config();
const express = require('express');
const bodyParser = require('body-parser');
const mysql = require('mysql2');
const bcrypt = require('bcrypt');
const path = require('path');



const app = express();
const port = process.env.PORT || 3000;


app.use(express.static(path.join(__dirname, 'public')));


app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());

//Supported via standard programming aids, creates the database connection
const db = mysql.createConnection({
    host: process.env.DB_HOST,
    user: process.env.DB_USER, 
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME 
});
//Supported via standard programming aids, if there an issue connecting to the database, an error message will be printed and will stop the node.js application
//else, we print that the connection to the database was successful
db.connect(err => {
    if (err) {
        console.error('Error connecting to the database:', err.message);
        process.exit(1);
    }
    console.log('Connected to MySQL!');
});

//Supported via standard programming aids
//.post allows us to send data to servers
app.post('/register', async (req, res) => {
    //gets the information required to register to the server
    const { username, email, password, confirmPassword } = req.body;
    //checks if something was entered into each field, if they were not, we respond with a 400 error
    if (!username || !email || !password || !confirmPassword) {
        return res.status(400).send('All fields are required.');
    }
    //checks if the two passwords the user entered match, if they do not, respond with a 400 error
    if (password !== confirmPassword) {
        return res.status(400).send('Passwords do not match!');
    }

    try {
        //encyrpts the password using bycrypt, creates a new random string call a salt that is appended to the password, then that password is put into a
        //a function that hashes it, meaning it cannot be reverted back to its cleartext form
        const hashedPassword = await bcrypt.hash(password, 10);

        //after hashing the password, we want to store this data into the sql database so we create a variable that stores the query that does that,
        //in which the questions marks are placeholders for the data that will be entered into the database
        const query = 'INSERT INTO users (username, email, password) VALUES (?, ?, ?)';
        //executes the database query
        db.query(query, [username, email, hashedPassword], (err, result) => {
            //error checking
            if (err) {
                //if the email is already in the database, we print a generic message because we do not want people knowing
                //that the email they entered already associated with an account
                if (err.code === 'ER_DUP_ENTRY') {
                    return res.status(400).send('Error registering');
                }
                console.error('Database error:', err);
                return res.status(500).send('An error occurred. Please try again.');
            }
            //if there are no errors, we print that the user registered succesfully
            res.redirect('/login.html?message=Successfully registered');
        });
    } catch (error) {
        console.error('Error during registration:', error);
        res.status(500).send('Internal Server Error');
    }
});

//Supported via standard programming aids
app.post('/login', (req, res) => {
    //gets the information required to login
    const { username, password } = req.body;

    //checks is the user entered something into both fields
    if (!username || !password) {
        return res.status(400).send('Username and password are required.');
    }

    //stores the query that checks the database for usernames matches the value entered
    const query = 'SELECT * FROM users WHERE username = ?';

    //executes the database query
    db.query(query, [username], async (err, results) => {
        if (err) {
            console.error('Database error:', err);
            return res.status(500).send('An error occurred. Please try again.');
        }

        //if the length of results is 0, it means that username was not found in the database
        if (results.length === 0) {
            return res.status(401).json({ success: false, message: 'Invalid username or password.' });
        }

        const user = results[0];

        //once we found the username in the database, we compare the password they entered with the password in the database
        const match = await bcrypt.compare(password, user.password);
        if (!match) {
            //if it does not match, the password was incorrect
            return res.status(401).send('Invalid username or password.');
        }
        console.log('Login successful for user:', username);
        //if the correct password was entered for the given username, the login is successful and redirects to main page
        res.redirect('/index.html?message=Login successful');
    });
});

//Supported via standard programming aids
app.post('/checkout', (req, res) => {
    //gets the information required to make a purchase
    const { cart, paymentDetails } = req.body;


    //if the user trys to buy something when there is nothing in the cart, we notify them that the cart is empty
    if (!cart || cart.length === 0) {
        return res.status(400).send('Cart is empty.');
    }

    //checks if there is information in all the fields
    if (!paymentDetails.cardName || !paymentDetails.cardNumber || !paymentDetails.expiry || !paymentDetails.cvc || 
        !paymentDetails.billingAddress || !paymentDetails.city || !paymentDetails.zip || !paymentDetails.country) {
        return res.status(400).send('Payment details are incomplete.');
    }

    //calculates the total cost of all the items in the cart
    const totalAmount = cart.reduce((total, item) => total + item.price, 0);

    //stores the database query
    const insertOrderQuery = `
        INSERT INTO orders (total_amount, card_name, billing_address, city, zip, country) 
        VALUES (?, ?, ?, ?, ?, ?)`;

    //executes the database query
    db.query(insertOrderQuery, [
        totalAmount, 
        paymentDetails.cardName, 
        paymentDetails.billingAddress, 
        paymentDetails.city, 
        paymentDetails.zip, 
        paymentDetails.country
    ], (err, result) => {
        if (err) {
            //if there is an error we send the client an error code
            return res.status(500).send('An error occurred while processing the order.');
        }

        //creates an Id so that we can keep of who purchased what in the order_items table
        const orderId = result.insertId;

        //creates an array of arrays, each element is an array that conatains the orderid, itemname, and price
        const cartItems = cart.map(item => [orderId, item.name, item.price]);

        //stores the database query 
        const insertCartItemsQuery = 'INSERT INTO order_items (order_id, item_name, price) VALUES ?';

        //executes the database query
        db.query(insertCartItemsQuery, [cartItems], (err) => {
            if (err) {
                return res.status(500).send('An error occurred while saving cart items.');
            }
            res.status(200).send('Payment processed successfully!');

        });
    });
});

//Supported via standard programming aids
app.post('/submit-contact', (req, res) => {
    //gets the information required to send a message
    const { firstName, lastName, email, phoneNumber, subject, message } = req.body;

    //ensures that all fields are filled out
    if (!firstName || !lastName || !email || !subject || !message || !phoneNumber) {
        return res.status(400).send('All fields are required');
    }

    //stores the query
    const query = `
        INSERT INTO faq_contacts (first_name, last_name, email, phone_number, subject, message)
        VALUES (?, ?, ?, ?, ?, ?)`;

    //executes the query
    db.query(query, [firstName, lastName, email, phoneNumber || null, subject, message], (err, result) => {
        if (err) {
            //if there is an error, we send an error code
            return res.status(500).send('An error occurred while submitting the form.');
        }
        //at this point, the information is in the database, so we send a reponse back to the client
        res.status(200).send('Your message has been submitted successfully.');
    });
});





app.listen(port, () => {
    console.log(`Server running at http://localhost:${port}`);
});

// Aided with basic GitHub coding tools
const mongoose = require('mongoose');
const logger = require('../utils/logger');

const connectDB = async (uri) => {
  try {
    // If uri is provided (testing environment), use it
    // Otherwise, use the environment variable
    const connectionString = uri || process.env.MONGO_URI;

    if (mongoose.connection.readyState === 1) {
      return; // Already connected
    }

    await mongoose.connect(connectionString);
    logger.info('MongoDB connected successfully');
  } catch (error) {
    logger.error(`MongoDB connection error: ${error.message}`);
    // Only exit in production environment
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  }
};

module.exports = connectDB;

const CACHE_VERSION = 1;

const BASE_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/search.json',
    '/manifest.json',
    '/favicon.png',
];

const OFFLINE_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/offline/index.html',
];

const NOT_FOUND_CACHE_FILES = [
    '/style.css',
    '/script.js',
    '/404.html',
];

const OFFLINE_PAGE = '/offline/index.html';
const NOT_FOUND_PAGE = '/404.html';

const CACHE_VERSIONS = {
    assets: 'assets-v' + CACHE_VERSION,
    content: 'content-v' + CACHE_VERSION,
    offline: 'offline-v' + CACHE_VERSION,
    notFound: '404-v' + CACHE_VERSION,
};

// Define MAX_TTL's in SECONDS for specific file extensions
const MAX_TTL = {
    '/': 3600,
    html: 3600,
    json: 86400,
    js: 86400,
    css: 86400,
};

const CACHE_BLACKLIST = [
    //(str) => {
    //    return !str.startsWith('http://localhost') && !str.startsWith('https://gohugohq.com');
    //},
];

const SUPPORTED_METHODS = [
    'GET',
];

/**
 * isBlackListed
 * @param {string} url
 * @returns {boolean}
 */
function isBlacklisted(url) {
    return (CACHE_BLACKLIST.length > 0) ? !CACHE_BLACKLIST.filter((rule) => {
        if(typeof rule === 'function') {
            return !rule(url);
        } else {
            return false;
        }
    }).length : false
}

/**
 * getFileExtension
 * @param {string} url
 * @returns {string}
 */
function getFileExtension(url) {
    let extension = url.split('.').reverse()[0].split('?')[0];
    return (extension.endsWith('/')) ? '/' : extension;
}

/**
 * getTTL
 * @param {string} url
 */
function getTTL(url) {
    if (typeof url === 'string') {
        let extension = getFileExtension(url);
        if (typeof MAX_TTL[extension] === 'number') {
            return MAX_TTL[extension];
        } else {
            return null;
        }
    } else {
        return null;
    }
}

/**
 * installServiceWorker
 * @returns {Promise}
 */
function installServiceWorker() {
    return Promise.all(
        [
            caches.open(CACHE_VERSIONS.assets)
                .then(
                    (cache) => {
                        return cache.addAll(BASE_CACHE_FILES);
                    }
                ),
            caches.open(CACHE_VERSIONS.offline)
                .then(
                    (cache) => {
                        return cache.addAll(OFFLINE_CACHE_FILES);
                    }
                ),
            caches.open(CACHE_VERSIONS.notFound)
                .then(
                    (cache) => {
                        return cache.addAll(NOT_FOUND_CACHE_FILES);
                    }
                )
        ]
    )
        .then(() => {
            return self.skipWaiting();
        });
}

/**
 * cleanupLegacyCache
 * @returns {Promise}
 */
function cleanupLegacyCache() {

    let currentCaches = Object.keys(CACHE_VERSIONS)
        .map(
            (key) => {
                return CACHE_VERSIONS[key];
            }
        );

    return new Promise(
        (resolve, reject) => {

            caches.keys()
                .then(
                    (keys) => {
                        return legacyKeys = keys.filter(
                            (key) => {
                                return !~currentCaches.indexOf(key);
                            }
                        );
                    }
                )
                .then(
                    (legacy) => {
                        if (legacy.length) {
                            Promise.all(
                                legacy.map(
                                    (legacyKey) => {
                                        return caches.delete(legacyKey)
                                    }
                                )
                            )
                                .then(
                                    () => {
                                        resolve()
                                    }
                                )
                                .catch(
                                    (err) => {
                                        reject(err);
                                    }
                                );
                        } else {
                            resolve();
                        }
                    }
                )
                .catch(
                    () => {
                        reject();
                    }
                );

        }
    );
}

function precacheUrl(url) {
    if(!isBlacklisted(url)) {
        caches.open(CACHE_VERSIONS.content)
            .then((cache) => {
                cache.match(url)
                    .then((response) => {
                        if(!response) {
                            return fetch(url)
                        } else {
                            // already in cache, nothing to do.
                            return null
                        }
                    })
                    .then((response) => {
                        if(response) {
                            return cache.put(url, response.clone());
                        } else {
                            return null;
                        }
                    });
            })
    }
}



self.addEventListener(
    'install', event => {
        event.waitUntil(
            Promise.all([
                installServiceWorker(),
                self.skipWaiting(),
            ])
        );
    }
);

// The activate handler takes care of cleaning up old caches.
self.addEventListener(
    'activate', event => {
        event.waitUntil(
            Promise.all(
                [
                    cleanupLegacyCache(),
                    self.clients.claim(),
                    self.skipWaiting(),
                ]
            )
                .catch(
                    (err) => {
                        event.skipWaiting();
                    }
                )
        );
    }
);

self.addEventListener(
    'fetch', event => {

        event.respondWith(
            caches.open(CACHE_VERSIONS.content)
                .then(
                    (cache) => {

                        return cache.match(event.request)
                            .then(
                                (response) => {

                                    if (response) {

                                        let headers = response.headers.entries();
                                        let date = null;

                                        for (let pair of headers) {
                                            if (pair[0] === 'date') {
                                                date = new Date(pair[1]);
                                            }
                                        }

                                        if (date) {
                                            let age = parseInt((new Date().getTime() - date.getTime()) / 1000);
                                            let ttl = getTTL(event.request.url);

                                            if (ttl && age > ttl) {

                                                return new Promise(
                                                    (resolve) => {

                                                        return fetch(event.request.clone())
                                                            .then(
                                                                (updatedResponse) => {
                                                                    if (updatedResponse) {
                                                                        cache.put(event.request, updatedResponse.clone());
                                                                        resolve(updatedResponse);
                                                                    } else {
                                                                        resolve(response)
                                                                    }
                                                                }
                                                            )
                                                            .catch(
                                                                () => {
                                                                    resolve(response);
                                                                }
                                                            );

                                                    }
                                                )
                                                    .catch(
                                                        (err) => {
                                                            return response;
                                                        }
                                                    );
                                            } else {
                                                return response;
                                            }

                                        } else {
                                            return response;
                                        }

                                    } else {
                                        return null;
                                    }
                                }
                            )
                            .then(
                                (response) => {
                                    if (response) {
                                        return response;
                                    } else {
                                        return fetch(event.request.clone())
                                            .then(
                                                (response) => {

                                                    if(response.status < 400) {
                                                        if (~SUPPORTED_METHODS.indexOf(event.request.method) && !isBlacklisted(event.request.url)) {
                                                            cache.put(event.request, response.clone());
                                                        }
                                                        return response;
                                                    } else {
                                                        return caches.open(CACHE_VERSIONS.notFound).then((cache) => {
                                                            return cache.match(NOT_FOUND_PAGE);
                                                        })
                                                    }
                                                }
                                            )
                                            .then((response) => {
                                                if(response) {
                                                    return response;
                                                }
                                            })
                                            .catch(
                                                () => {

                                                    return caches.open(CACHE_VERSIONS.offline)
                                                        .then(
                                                            (offlineCache) => {
                                                                return offlineCache.match(OFFLINE_PAGE)
                                                            }
                                                        )

                                                }
                                            );
                                    }
                                }
                            )
                            .catch(
                                (error) => {
                                    console.error('  Error in fetch handler:', error);
                                    throw error;
                                }
                            );
                    }
                )
        );

    }
);


self.addEventListener('message', (event) => {

    if(
        typeof event.data === 'object' &&
        typeof event.data.action === 'string'
    ) {
        switch(event.data.action) {
            case 'cache' :
                precacheUrl(event.data.url);
                break;
            default :
                console.log('Unknown action: ' + event.data.action);
                break;
        }
    }

});

