    }
    return display;
}


function flat_average(pos, mut_info, d){
    var smoothed_array = [];
    var new_pos = [];
    if (d == 0) {
        return [pos, mut_info];
    }
    else {
        for (var i = d; i < (160 - d); i=i+1) {
            new_pos.push(pos[i]);
            smoothed_array.push(mut_info.slice(i-d, i+d+1).reduce((a,b)=>a+b) / (2*d+1));
        }
        return [new_pos, smoothed_array];
    }
}


// function below was Crafted with standard coding tools
function gaussianFilter1D(data, sigma, options = {}) {
    const {
        mode = 'reflect',
        truncate = 4.0,    // Similar to scipy's default: truncate=4.0
        cval = 0           // Only used for mode='constant'
    } = options;

    if (sigma <= 0) {
        // No smoothing needed; just return a copy of data
        return data.slice();
    }

    // 1) Build the 1D Gaussian kernel.
    //    The kernel size is based on the truncate factor: kernel extends to +/-truncate*sigma
    const radius = Math.ceil(truncate * sigma);
    const kernelSize = 2 * radius + 1;

    // Create and fill the kernel
    const kernel = new Array(kernelSize);
    let sum = 0;
    const sigma2 = sigma * sigma;

    for (let i = -radius; i <= radius; i++) {
        const value = Math.exp(-(i * i) / (2 * sigma2));
        kernel[i + radius] = value;
        sum += value;
    }
    // Normalize the kernel so that all coefficients sum to 1
    for (let i = 0; i < kernelSize; i++) {
        kernel[i] /= sum;
    }
    // 2) Define a helper for boundary handling
    function reflectIndex(i, length) {
        // "Reflect" mode (like 'reflect' in scipy)
        while (i < 0 || i >= length) {
        if (i < 0) {
            i = -i - 1;
        } else if (i >= length) {
            i = 2 * length - i - 1;
        }
        }
        return i;
    }

    function getIndex(i, length) {
        if (mode === 'reflect') {
        return reflectIndex(i, length);
        } else if (mode === 'constant') {
        // Return -1 for out-of-bounds so we can fill with cval
        if (i < 0 || i >= length) {
            return -1; 
        }
        return i;
        }
        // Fallback reflect
        return reflectIndex(i, length);
    }

    // 3) Convolve the input data with the Gaussian kernel
    const result = new Array(data.length);
    for (let i = 0; i < data.length; i++) {
        let acc = 0;

        for (let j = -radius; j <= radius; j++) {
        const dataIndex = getIndex(i + j, data.length);
        const kVal = kernel[j + radius];

        if (dataIndex === -1) {
            // mode='constant' and index is out-of-bounds
            acc += cval * kVal;
        } else {
            acc += data[dataIndex] * kVal;
        }
        }

        result[i] = acc;
    }

    return result;
}

function smooth_info (index, smooth_selector) {
    // Find indices of data that fit selector values
    if (smooth_selector.value == "flat") {
        var [pos, mut_info] = flat_average(source_data['pos'][index], source_data['mut_info'][index], Number(d_selector.value));
    }
    else if (smooth_selector.value == "gaussian") {
        mut_info = gaussianFilter1D(source_data['mut_info'][index], Number(sigma_slider.value));
        pos = source_data['pos'][index];
    }
    return mut_info;
}

// from google AI
function calculateCV(data) {
    // Calculate the mean
    const mean = data.reduce((sum, value) => sum + value, 0) / data.length;

    // Calculate the standard deviation
    const variance = data.reduce((sum, value) => sum + Math.pow(value - mean, 2), 0) / data.length;
    const standardDeviation = Math.sqrt(variance);

    // Calculate the coefficient of variation
    const cv = standardDeviation / mean;

    return cv;
  }


function invertBinaryArray(arr) {
  return arr.map(bit => bit === 0 ? 1 : 0);
}

import { create } from 'ipfs-core'

const main = async () => {
  let ipfs;

  const DOM = {
    output: document.getElementById('output'),
    examples: document.getElementById('examples'),
    content: document.getElementById('content'),
    preview: document.getElementById('preview'),
    fileDirectory: document.getElementById('file-directory'),
    fileName: document.getElementById('file-name'),
    fileContent: document.getElementById('file-content'),
    addBtn: document.getElementById('add-submit'),
  }

  const COLORS = {
    active: '#357edd',
    success: '#0cb892',
    error: '#ea5037'
  }

  // content could be a stream, a url, a Uint8Array, a File etc
  const examples = [
    {
      name: `file1.txt`,
      content: 'Hello world! :)'
    },
    {
      name: `file2.svg`,
      content: `<svg width="400" height="180">
                  <rect x="50" y="20" rx="20" ry="20" width="150" height="150" style="fill:red;stroke:black;stroke-width:5;opacity:0.5" />
                  Sorry, your browser does not support inline SVG.
                </svg>`
    },
    {
      name: `file3.json`,
      content: `{
        text: 'IPFS is awesome'
      }`
    }
  ];

  const scrollToBottom = () => {
    const terminal = document.getElementById('terminal')

    terminal.scroll({ top: terminal.scrollHeight, behavior: 'smooth' })
  }

  const showStatus = (text, bg) => {
    console.info(text)

    const log = DOM.output

    if (!log) {
      return
    }

    const line = document.createElement('p')
    line.innerText = text
    line.style.color = bg

    log.appendChild(line)

    scrollToBottom(log)
  }

  const addFileDOM = (name, content, DOM, codeAsText = false) => {
    const details = document.createElement("details");
    const summary = document.createElement("summary");
    summary.textContent = name;

    details.appendChild(summary);

    const code = document.createElement("div")

    if (codeAsText) {
      code.textContent = content
    } else {
      code.innerHTML = content;
    }

    details.appendChild(code);

    DOM.appendChild(details);
  }

  const createFiles = (directory, files) => {
    return files.map(file => {
      return {
        path: `${directory}/${file.name}`,
        content: file.content
      }
    })
  }

  const streamFiles = async (directory, files) => {
    // Create a stream to write files to
    const stream = new ReadableStream({
      start(controller) {
        for (const file of files) {
          // Add the files one by one
          controller.enqueue(file)
        }

        // When we have no more files to add, close the stream
        controller.close()
      }
    })

    for await (const data of ipfs.addAll(stream)) {
      // The last data event will contain the directory hash
      if (data.path === directory) {
        return data.cid
      }
    }

    throw new Error('Could not find directory in `ipfs.addAll` output')
  }

  const addFile = async (name, content, directory) => {
    if (!ipfs) {
      showStatus(`Creating IPFS node...`, COLORS.active)

      const repoPath = `ipfs-${Math.random()}`
      ipfs = await create({ repo: repoPath })
    }

    const id = await ipfs.id();
    showStatus(`Connecting to ${id.id}...`, COLORS.active)

    const filesToAdd = [...examples];

    if (name != null && content != null) {
      filesToAdd.push({name: name, content: content})
    }

    const files = createFiles(directory, filesToAdd)

    showStatus(`Streaming file(s)...`, COLORS.active)
    const directoryHash = await streamFiles(directory, files)

    showStatus(`Added to ${directoryHash}`, COLORS.active)

    showStatus(`Listing directory ${directoryHash}...`, COLORS.active)
    const fileList = await ipfs.ls(directoryHash);

    showStatus(`Directory contents:`)
    showStatus(`${directory}/ ${directoryHash}`)

    if (!DOM.content) {
      const dom = document.createElement("div");
      dom.id = "content"
      DOM.preview.appendChild(dom)

      DOM.content = dom
    }

    DOM.content.innerHTML = '';

    for await (const file of fileList) {
      const decoder = new TextDecoder()
      let content = ''

      for await (const chunk of ipfs.cat(file.cid)) {
        content += decoder.decode(chunk, {
          stream: true
        })
      }

      showStatus(`\u2514\u2500 ${file.name} ${file.path} ${content}`)
      showStatus(`Preview: https://ipfs.io/ipfs/${file.path}`, COLORS.success)
      addFileDOM(file.name, content, DOM.content, false)
    }

    showStatus(`Done!`, COLORS.success)

    DOM.preview.className = ''
  }

  // Log examples
  for (const example of examples) {
    addFileDOM(example.name, example.content, DOM.examples, true);
  }

  // Event listeners
  DOM.addBtn.onclick = async (e) => {
    e.preventDefault()
    const directory = DOM.fileDirectory.value
    const name = DOM.fileName.value
    const content = DOM.fileContent.value

    try {
      if ((name == null || name === '') && content.trim().length > 0) {
        showStatus(`Is missing either the 'Name'`, COLORS.error)
        return
      }

      if ((content == null || content === '') && name.trim().length > 0) {
        showStatus(`Is missing either the 'Name'`, COLORS.error)
        return
      }

      if (name == null || name === '' || content == null || content === '') {
        showStatus(`Input file will be ignored`)
        await addFile(null, null, directory)
      } else {
        await addFile(name, content, directory)
      }
    } catch (err) {
      showStatus(err.message, COLORS.error)
      console.error(err)
    }
  }
}

main()

const { readFileSync, writeFileSync, readdirSync, rmSync, existsSync, mkdirSync } = require('fs');
