  let arr = lorem.split('.');
  return { lorem, arr };
});

Benchmark.add('match replace', ({ lorem }) => {
  while (true) {
    const last = lorem.match(/\.([^.]*?)$/g) || [];
    if (last.length === 0) { break; }
    const current = (last[0] || '').replace('.', '');
    const path = lorem;
    lorem = lorem.replace(/\.([^.]*?)$/g, "")
  }
})

Benchmark.add('lastIndexOf slice', ({ lorem }) => {
  while (true) {
    const lastIndex = lorem.lastIndexOf('.');
    if (lastIndex === -1) { break; }
    const current = lorem.slice(lastIndex + 1)
    const path = lorem;
    lorem = lorem.slice(0, lastIndex)
  }
})

Benchmark.add('lastIndexOf substr', ({ lorem }) => {
  while (true) {
    const lastIndex = lorem.lastIndexOf('.');
    if (lastIndex === -1) { break; }
    const current = lorem.substr(lastIndex + 1)
    const path = lorem;
    lorem = lorem.substr(0, lastIndex)
  }
})

Benchmark.add('pop join', ({ arr }) => {
  while (arr.length > 0) {
    const current = arr[arr.length - 1];
    const path = arr.join('.');
    arr.pop();
  }
})

Benchmark.add('pop', ({ arr }) => {
  while (arr.length > 0) {
    const current = arr[arr.length - 1];
    arr.pop();
  }
})

Benchmark.add('split pop join', ({ lorem, arr }) => {
  lorem.split('.');
  while (arr.length > 0) {
    const current = arr[arr.length - 1];
    const path = arr.join('.');
    arr.pop();
  }
})

Benchmark.run();

