/**

 * Convert a hex color value to rgb format.
 * @param {string} hex - The hex value of the color.
 * @returns {string} - The color in rgb format (e.g., "rgb(255 128 0)").
 */
export const hexToRgb = (/** @type {string} */ hex) => {
	// Remove the hash symbol, if present
	hex = hex.replace(/^#/, '');
	// if hex entered as #abc, convert to #aabbcc
	if (hex.length === 3) hex = [...hex].map((x) => x + x).join('');
	let bigint = parseInt(hex, 16);
	let r = (bigint >> 16) & 255;
	let g = (bigint >> 8) & 255;
	let b = bigint & 255;
	return 'rgb(' + r + ' ' + g + ' ' + b + ')';
};

/**
 * Composed with GitHub coding tools AI but matches existing code found elsewhere
 * Convert a hex color value to HSL format.
 * @param {string} hex - The hex value of the color.
 * @returns {string} - The color in HSL format (e.g., "hsl(0, 100%, 50%)").
 */
export const hexToHsl = (hex) => {
	// Handle empty or invalid hex values
	if (!hex || hex === '') return '';

	// Remove the hash symbol if present
	hex = hex.replace(/^#/, '');

	// Check if it's a 3-character hex value
	if (hex.length === 3) {
		// Convert to 6-character form by doubling each character
		hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
	}

	// Parse the hex string to an integer
	let bigint = parseInt(hex, 16);

	// Extract RGB components using bit shifting
	let r = ((bigint >> 16) & 255) / 255;
	let g = ((bigint >> 8) & 255) / 255;
	let b = (bigint & 255) / 255;

	// Find the minimum and maximum values of r, g, b
	let max = Math.max(r, g, b);
	let min = Math.min(r, g, b);

	// Calculate the lightness
	let l = (max + min) / 2;

	let h = 0,
		s = 0;

	if (max === min) {
		// Achromatic (gray)
		h = 0;
		s = 0;
	} else {
		// Calculate saturation
		s = l > 0.5 ? (max - min) / (2 - max - min) : (max - min) / (max + min);

		// Calculate hue
		switch (max) {
			case r:
				h = (g - b) / (max - min) + (g < b ? 6 : 0);
				break;
			case g:
				h = (b - r) / (max - min) + 2;
				break;
			case b:
				h = (r - g) / (max - min) + 4;
				break;
		}
		h /= 6;
	}

	// Convert to degrees, percentages
	h = Math.round(h * 360);
	s = Math.round(s * 100);
	l = Math.round(l * 100);

	return `hsl(${h}deg ${s}% ${l}%)`;
};

/**
 * Converts HSL values to RGB.
 * @param {number} h - Hue (0-360)
 * @param {number} s - Saturation (0-100)
 * @param {number} l - Lightness (0-100)
 * @returns {object} - An object containing r, g, b numeric values (0-255).
 */
export function hslToRgb(h, s, l) {
	s /= 100;
	l /= 100;

	const c = (1 - Math.abs(2 * l - 1)) * s;
	const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
	const m = l - c / 2;

	let r, g, b;

	if (h >= 0 && h < 60) {
		r = c;
		g = x;
		b = 0;
	} else if (h >= 60 && h < 120) {
		r = x;
		g = c;
		b = 0;
	} else if (h >= 120 && h < 180) {
		r = 0;
		g = c;
		b = x;
	} else if (h >= 180 && h < 240) {
		r = 0;
		g = x;
		b = c;
	} else if (h >= 240 && h < 300) {
		r = x;
		g = 0;
		b = c;
	} else {
		r = c;
		g = 0;
		b = x;
	}

	return {
		r: Math.round((r + m) * 255),
		g: Math.round((g + m) * 255),
		b: Math.round((b + m) * 255)
	};
}

/**
 * Extracts individual color values from an RGB string.
 * @param {string} rgb - The RGB string (e.g., "rgb(143 188 143)" or "rgb(143, 188, 143)").
 * @returns {object} - An object containing r, g, and b numeric values.
 */
export function rgbToValues(rgb) {
	// Remove "rgb(" and ")" and split by spaces or commas
	const cleanedStr = rgb.replace(/^rgb\(|\)$/g, '').trim();
	const values = cleanedStr.split(/[\s,]+/);

	if (values.length >= 3) {
		return {
			r: parseInt(values[0], 10),
			g: parseInt(values[1], 10),
			b: parseInt(values[2], 10)
		};
	}

	// Return default values if parsing fails
	return { r: 0, g: 0, b: 0 };
}

/**
 * Converts an RGB color string to a hex color string.
 * @param {string} rgbString - The RGB string (e.g., "rgb(143 188 143)").
 * @returns {string} - The color in hex format (e.g., "#8FBC8F").
 */
export function rgbToHex(rgbString) {
	// Extract r, g, b values from the RGB string
	const { r, g, b } = rgbToValues(rgbString);

	// Convert RGB values to hex string
	return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase()}`;
}

/**
 * Converts an HSL color string to an RGB color string.
 * @param {string} hslString - The HSL string (e.g., "hsl(120deg 25% 65%)").
 * @returns {string} - The color in RGB format (e.g., "rgb(143 188 143)").
 */
export function hslStringToRgbString(hslString) {
	// Extract h, s, l values from the HSL string
	// @ts-ignore
	const { h, s, l } = hslToValues(hslString);

	// Convert HSL values to RGB values
	const { r, g, b } = hslToRgb(h, s, l);

	// Format as RGB string
	return `rgb(${r} ${g} ${b})`;
}

/**
 * Extracts individual color values from an HSL string.
 * @param {string} hsl - The HSL string (e.g., "hsl(120deg 25% 65%)" or "hsl(120, 25%, 65%)").
 * @returns {object} - An object containing h, s, and l numeric values.
 */
export function hslToValues(hsl) {
	// Remove "hsl(" and ")" and split by spaces or commas
	const cleanedStr = hsl.replace(/^hsl\(|\)$/g, '').trim();
	const parts = cleanedStr.split(/[\s,]+/);

	let h = parseInt(parts[0]);
	let s = parseInt(parts[1]);
	let l = parseInt(parts[2]);

	// Check if h has "deg" suffix and remove it
	if (isNaN(h) && typeof parts[0] === 'string' && parts[0].endsWith('deg')) {
		h = parseInt(parts[0].replace('deg', ''));
	}

	// Remove percentage symbols if present
	if (isNaN(s) && typeof parts[1] === 'string') {
		s = parseInt(parts[1].replace('%', ''));
	}
	if (isNaN(l) && typeof parts[2] === 'string') {
		l = parseInt(parts[2].replace('%', ''));
	}

	// Return default values if parsing fails
	return {
		h: isNaN(h) ? 0 : h,
		s: isNaN(s) ? 0 : s,
		l: isNaN(l) ? 0 : l
	};
}

/**
 * Calculates the average of two RGB colors.
 * @param {string} rgbColor1 - First RGB color string (e.g., "rgb(143 188 143)")
 * @param {string} rgbColor2 - Second RGB color string (e.g., "rgb(200 100 50)")
 * @returns {string} - The average RGB color as a string (e.g., "rgb(171 144 96)")
 */
export function getAverageRgb(rgbColor1, rgbColor2) {
	// Extract RGB values from both colors
	const color1 = rgbToValues(rgbColor1);
	const color2 = rgbToValues(rgbColor2);

	// Calculate average values
	const avgR = Math.round((color1.r + color2.r) / 2);
	const avgG = Math.round((color1.g + color2.g) / 2);
	const avgB = Math.round((color1.b + color2.b) / 2);

	// Return as RGB string
	return `rgb(${avgR} ${avgG} ${avgB})`;
}

/**
 * Calculate the lightness of a color.
 * @param {string} hex - The hex value of the color.
 * @returns {number} - The lightness of the color, ranging from 0 to 255.
 */
export function getLightness(hex) {
	let bigint = parseInt(hex.slice(1), 16);
	let r = (bigint >> 16) & 255;
	let g = (bigint >> 8) & 255;
	let b = bigint & 255;

	// Calculate lightness
	const max = Math.max(r, g, b);
	const min = Math.min(r, g, b);
	const lightness = (max + min) / 2;

	return Math.round((lightness / 256) * 100);
}

/**
 * Calculate the intensity of a color.
 * @param {string} hex - The hex value of the color.
 * @returns {number} - The intensity of the color, ranging from 0 to 255.
 */
export function getIntensity(hex) {
	let bigint = parseInt(hex.slice(1), 16);
	let r = (bigint >> 16) & 255;
	let g = (bigint >> 8) & 255;
	let b = bigint & 255;
	return Math.round((r + g + b) / 3);
}

/**
 * Calculate the brightness of a color.
 * @param {string} hex - The hex value of the color.
 * @returns {number} - The brightness of the color, ranging from 0 to 255.
 */
export function getBrightness(hex) {
	let bigint = parseInt(hex.slice(1), 16);
	let r = (bigint >> 16) & 255;
	let g = (bigint >> 8) & 255;
	let b = bigint & 255;
	return Math.round((r * 299 + g * 587 + b * 114) / 1000);
}

