/* Load Car Data Access Object */
const CarDao = require('../dao/carDao');

/* Load Controller Common function */
const ControllerCommon = require('./common/controllerCommon');

/* Load Car entity */
const Car = require('../model/car');

/**
 * Car Controller
 */
class CarController {

    constructor() {
        this.carDao = new CarDao();
        this.common = new ControllerCommon();
    }

    /**
     * Tries to find an entity using its Id / Primary Key
     * @params req, res
     * @return entity
     */
    findById(req, res) {
        let id = req.params.id;

        this.carDao.findById(id)
            .then(this.common.findSuccess(res))
            .catch(this.common.findError(res));
    };

    /**
     * Finds all entities.
     * @return all entities
     */
    findAll(res) {
        this.carDao.findAll()
            .then(this.common.findSuccess(res))
            .catch(this.common.findError(res));
    };

    /**
     * Counts all the records present in the database
     * @return count
     */
    countAll(res) {

        this.carDao.countAll()
            .then(this.common.findSuccess(res))
            .catch(this.common.serverError(res));
    };

    /**
     * Updates the given entity in the database
     * @params req, res
     * @return true if the entity has been updated, false if not found and not updated
     */
    update(req, res) {
        let car = new Car();
        car.id = req.body.id;
        car.maker = req.body.maker;
        car.model = req.body.model;
        car.year = req.body.year;
        car.driver = req.body.driver;

        return this.carDao.update(car)
            .then(this.common.editSuccess(res))
            .catch(this.common.serverError(res));
    };

    /**
     * Creates the given entity in the database
     * @params req, res
     * returns database insertion status
     */
    create(req, res) {
        let car = new Car();
        if (req.body.id) {
            car.id = req.body.id;
        }
        car.maker = req.body.maker;
        car.model = req.body.model;
        car.year = req.body.year;
        car.driver = req.body.driver;

        if (req.body.id) {
            return this.carDao.createWithId(car)
                .then(this.common.editSuccess(res))
                .catch(this.common.serverError(res));
        }
        else {
            return this.carDao.create(car)
                .then(this.common.editSuccess(res))
                .catch(this.common.serverError(res));
        }

    };

    /**
     * Deletes an entity using its Id / Primary Key
     * @params req, res
     * returns database deletion status
     */
    deleteById(req, res) {
        let id = req.params.id;

        this.carDao.deleteById(id)
            .then(this.common.editSuccess(res))
            .catch(this.common.serverError(res));
    };

    /**
     * Returns true if an entity exists with the given Id / Primary Key
     * @params req, res
     * @return
     */
    exists(req, res) {
        let id = req.params.id;

        this.carDao.exists(id)
            .then(this.common.existsSuccess(res))
            .catch(this.common.findError(res));
    };
}

module.exports = CarController;

import React, { useState, useEffect } from "react";
import {
  TextField,
  Paper,
  Radio,
  RadioGroup,
  FormControlLabel,
  Grid,
  Typography,
} from "@mui/material";
import { css } from "@emotion/react";
import styled from "@emotion/styled";
import SpeedDisplay from "../components/SpeedDisplay.js";
import { paceToSpeed } from "../services/speedService.js";
import * as consts from "../services/unitConstants.js";

const Subheader = styled.div`
  text-align: left;
  margin-left: -20px;
  margin-right: -20px;
  background: #f5f5f5;
  padding-left: 20px;
`;

const CalculatorBox = styled(Paper)`
  padding: 20px;
  text-align: center;
  max-width: 600px;
  display: flex;
`;

export default function SpeedConverter(props) {
  const [paceUnit, setUnitValue] = useState(consts.paceTypes.MIN_KM);
  const [pace, setPaceValue] = useState();
  const [speed, setSpeedValue] = useState(0);

  useEffect(() => {
    paceChanged();
  }, [pace, paceUnit]);

  function handleUnitChange(event) {
    setUnitValue(parseInt(event.target.value));
  }

  function handlePaceChange(event) {
    setPaceValue(event.target.value);
  }

  function paceChanged() {
    setSpeedValue(paceToSpeed(pace, paceUnit));
  }

  return (
    <div style={{ display: "flex", justifyContent: "center" }}>

      <CalculatorBox className="calculatorBox" elevation={3}>

        <Grid container direction="row" justifyContent="center" alignItems="center">
<Grid item xs={12} style={{ paddingBottom: "20px" }}>
        <Subheader>
          <Typography variant="overline">Pace</Typography>
        </Subheader>
        </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              id="pace"
              name="pace"
              label="pace"
              type="number"
              value={pace}
              onChange={handlePaceChange}
              variant="standard"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <RadioGroup
              aria-label="pace unit"
              name="paceUnit"
              value={paceUnit}
              onChange={handleUnitChange}
            >
              <Grid container direction="row" justifyContent="center" alignItems="center">
                <Grid item xs={3}>
                  <FormControlLabel
                    value={consts.paceTypes.MIN_KM}
                    labelPlacement="bottom"
                    control={<Radio />}
                    label="min/km"
                  />
                </Grid>
                <Grid item xs={3}>
                  <FormControlLabel
                    value={consts.paceTypes.KM_H}
                    labelPlacement="bottom"
                    control={<Radio />}
                    label="km/h"
                  />
                </Grid>
                <Grid item xs={3}>
                  <FormControlLabel
                    value={consts.paceTypes.MIN_MI}
                    labelPlacement="bottom"
                    control={<Radio />}
                    label="min/mi"
                  />
                </Grid>
                <Grid item xs={3}>
                  <FormControlLabel
                    value={consts.paceTypes.MPH}
                    labelPlacement="bottom"
                    control={<Radio />}
                    label="mph"
                  />
                </Grid>
               </Grid>
             </RadioGroup>
           </Grid>
           <Grid item xs={12} style={{ paddingTop: "40px" }}> 
             <Subheader>
               <Typography variant="overline">Speed & pace</Typography>
             </Subheader>
             <SpeedDisplay speed={speed} />
           </Grid>
         </Grid>
       </CalculatorBox>
     </div>
   );
 }             














