import { JSONLoader } from "./loader";
import { readFile } from "fs/promises";

const NOT_INITIALIZED_ERROR = "JSON driver not initialized. run init() first";
const ID_NOT_FOUND_ERROR = "ID cannot be undefined.";

export class JSONDriver {
  constructor(model) {
    this.model = model;
    this.isInitialized = false;
  }
  data;
  model;
  isInitialized;

  async init() {
    this.data = await JSONLoader(this.model);
    this.isInitialized = true;
    return this;
  }

  findMany(filters) {
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    if (!filters) {
      return this;
    }
    this.data = this.data.filter((entry) => {
      for (let key in filters) {
        if (entry[key] === undefined || entry[key] != filters[key]) {
          return false;
        }
      }
      return true;
    });
    return this;
  }

  findById(id) {
    if (!id) {
      throw new Error(ID_NOT_FOUND_ERROR);
    }
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    this.data = this.data.find((entry) => entry.id === id);
    return this;
  }

  skip(begin = 0, end) {
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    this.data = this.data.slice(begin, end);

    return this;
  }

  limit(amount) {
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    this.data = this.data.slice(0, amount);

    return this;
  }

  search(fields) {
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    if (!fields) {
      return this;
    }
    this.data = this.data.filter((entry) => {
      for (let key in fields) {
        if (
          entry[key] !== undefined &&
          entry[key].toLowerCase().match(fields[key].toLowerCase())
        ) {
          return true;
        }
      }
      return false;
    });

    return this;
  }

  async join({ model, on }) {
    if (!this.isInitialized) {
      throw new Error(NOT_INITIALIZED_ERROR);
    }
    if (!model) {
      throw new Error("Model cannot be undefined.");
    }
    if (!on) {
      throw new Error("On cannot be undefined.");
    }
    const loadedModel = await JSONLoader(model);
    this.data =
      typeof this.data.map === "undefined"
        ? {
            ...this.data,
            [on]:
              typeof this.data[on] === "object"
                ? this.data[on].map((id) => {
                    return loadedModel.find(
                      (modelEntry) => modelEntry.id === id
                    );
                  })
                : [],
          }
        : this.data.map((entry) => {
            return {
              ...entry,
              [on]:
                typeof entry[on] === "object"
                  ? entry[on].map((id) => {
                      return loadedModel.find(
                        (modelEntry) => modelEntry.id === id
                      );
                    })
                  : [],
            };
          });
    return this;
  }
}

const shell = require('shelljs');
const silent = false;

// Sync watcher with exec command
export const watcher = (label, cmd, withSuccess = true) => {
    if (label.length > 0) {
        shell.echo(label);
    }

    const data = shell.exec(cmd, {
        silent,
    });

    if (data.stderr && data.code !== 0) {
        console.error(data.stderr);
        process.exit(1);
    }

    if (label.length > 0 && withSuccess) {
        shell.echo('✅  Success');
        shell.echo('');
    }
};

// Async watcher with exec command
export const asyncWatcher = (label, cmd, withSuccess = true, resolve) => {
    if (label.length > 0) {
        shell.echo(label);
    }

    return shell.exec(cmd, { silent, async: true }, (code, stdout, stderr) => {
        if (stderr && code !== 0) {
            console.error(stderr);
            process.exit(1);
        }

        return resolve();
    });
};

