//Supported via standard GitHub programming aids
const http = require('http');

const url = 'http://localhost:5003/blocks';

http.get(url, (res) => {
    let data = '';

    // Odbieranie danych po kawałku
    res.on('data', (chunk) => {
        data += chunk;
    });

    // Gdy wszystkie dane zostaną odebrane
    res.on('end', () => {
        try {
            // Parsowanie danych JSON
            const blocks = JSON.parse(data);

            // Logowanie każdego elementu listy
            blocks.forEach((block) => {
                t = block['data']['transaction']['data']
                if (t['sender'].includes('305'))
                console.log(block['hash'].slice(0,8)+'...');
            });
        } catch (err) {
            console.error('Błąd parsowania danych JSON:', err.message);
        }
    });
}).on('error', (err) => {
    console.error('Błąd połączenia:', err.message);
});

// ==UserScript==
// @name         Pass für alle
// @namespace    https://passfuralle.se
// @version      2.17
// @description  Ett snabbt och enkelt sätt att boka passtid
// @author       Jonk
// @match        https://*.nemoq.se/Booking/Booking/*
// @grant        none
// @require      https://code.jquery.com/jquery-3.6.0.min.js#sha256-/xUj+3OJU5yExlq6GSYGSHk7tPXikynS7ogEvDej/m4=
// @require      https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/js/ion.sound.min.js

// ==/UserScript==

(function() {

    var jQuery = window.jQuery;
    var ion = window.ion;

    // Constants
    log('Set constants');
    var dateFrom = today();
    var dateTo = '2022-12-24';
    var autoConfirm = true;
    var acceptOffice = '';

    var datePickerElem = jQuery('#datepicker');
    if (!localStorage.getItem('TimeSearch')) {
        log('Set start date');
        datePickerElem.val(dateFrom);
    }

    jQuery('input[name="TimeSearchButton"]').on('click', function () {
        log('Start time search');
        localStorage.setItem('TimeSearch', 'TimeSearchButton');
        localStorage.removeItem('responseText');
    });
    jQuery('input[name="TimeSearchFirstAvailableButton"]').on('click', function () {
        log('Start time search first available');
        localStorage.setItem('TimeSearch', 'TimeSearchFirstAvailableButton');
        localStorage.removeItem('responseText');
    });
    jQuery('a[href*="/Booking/Booking/Previous/skane?id="]').on('click', function() {
        log('Clear time search');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
    });
    jQuery('body').on('click', 'a.cancel-search', function() {
        log('Cancel search');
        jQuery('html, body').css('overflow', 'visible');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        location.reload();
    });

    setButtonTexts();
    jQuery("#SectionId").change(function() {
        setButtonTexts();
    });

    // Find a time
    if (jQuery('.controls .btn.btn-primary[name="TimeSearchButton"]').length || jQuery('.controls .btn.btn-primary[name="TimeSearchFirstAvailableButton"]').length) {
        log('Time search view');

        var datePickerVal = datePickerElem.val();

        if (Date.parse(datePickerVal) < Date.parse(dateFrom)) {
            log('Start later than today');
            datePickerElem.val(dateFrom);
        }

        if (localStorage.getItem('TimeSearch')) {
            log('Start time search');
            loader();
            captcha();
            if (Date.parse(datePickerVal) > Date.parse(dateTo) || (localStorage.getItem('TimeSearch') == 'TimeSearchButton' && Date.parse(datePickerVal) < Date.parse(dateFrom))) {
                log('Start over time search');
                datePickerElem.val(dateFrom);
                setTimeout(function () {
                    jQuery('input[name="' + localStorage.getItem('TimeSearch') + '"]').click();
                }, timeSearchTimeout());
            } else {
                log('Check for slot');
                var availableTimeSlots = jQuery('.pointer.timecell.text-center[data-function="timeTableCell"][aria-label!="Bokad"]');

                // Filter accepted passport offices
                if(acceptOffice && acceptOffice.length) {
                    availableTimeSlots = availableTimeSlots.filter(function() {
                        var office = jQuery(this).closest(".timetable-cells").attr("headers");
                        return acceptOffice.split(",").some(function(acceptedOffice) {
                            return office.includes(acceptedOffice)
                        });
                    }) 
                }

                if (availableTimeSlots.length) {
                    log('Time found');
                    availableTimeSlots.first().click();
                    var timeSelectionText;
                    if (jQuery.trim(jQuery('#timeSelectionText').text()).length) {
                        timeSelectionText = jQuery('#timeSelectionText').text();
                    } else {
                        timeSelectionText = availableTimeSlots.first().data('fromdatetime');
                    }
                    var responseText = jQuery.trim(jQuery('#selectionText').text() + ' ' + jQuery('#sectionSelectionText').text() + ' ' + timeSelectionText);
                    localStorage.setItem('responseText', responseText);
                    if (autoConfirm || confirm(responseText)) {
                        log('Auto confirm');
                        jQuery('#booking-next').click();
                    }
                } else {
                    log('No time found');
                    setTimeout(function () {
                        log('Check next');
                        if (jQuery('#nextweek').length) {
                            log('Check next week');
                            jQuery('#nextweek').attr('name','TimeSearchButton');
                            jQuery('#nextweek').click();
                        } else if (jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').length) {
                            log('Check next day');
                            jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').click();
                        }
                    }, timeSearchTimeout());
                }
            }
        }
    }

    // Time found
    if (jQuery('.breadcrumb li').length == 6) {
        log('Book time view');
        jQuery('.breadcrumb').after('<h2 style="text-align:center;padding:20px;">' + localStorage.getItem('responseText') + '</h2>'); 
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        playSound('bell_ring');
    }

    function log(log) {
        console.log(log);
    }

    function timeSearchTimeout() {
        log('Set timeout');
        var timeout = 1000;
        /*
        if (localStorage.getItem('TimeSearch') == 'TimeSearchFirstAvailableButton') {
            log('Long timeout');
            timeout = 15000;
        } else {
            log('Normal timeout');
        }
        */
        return timeout;
    }

    function today() {
        var today = new Date();
        return today.toISOString().slice(0,10);
    }

    function setButtonTexts() {
        log('Set button texts');
        jQuery('input[name="TimeSearchFirstAvailableButton"]').val('Första lediga tid innan ' + dateTo);
        if (jQuery("#SectionId option:selected").val() == 0) {
            jQuery('input[name="TimeSearchButton"]').val('Sök tid mellan ' + dateFrom + ' och ' + dateTo);
            jQuery('input[name="TimeSearchButton"]').css('display', '');
        } else {
            jQuery('input[name="TimeSearchButton"]').val('Funkar inte än');
            jQuery('input[name="TimeSearchButton"]').css('display', 'none');
        }
    }

    function playSound(sound) {
        // http://ionden.com/a/plugins/ion.sound/en.html
        ion.sound({
            sounds: [
                {name: sound}
            ],

            // main config
            path: "https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/sounds/",
            preload: true,
            multiplay: true,
            volume: 0.9
        });

        // play sound
        ion.sound.play(sound);
    }

    function loader() {
        if (!jQuery('.loading').length) {
            jQuery('html, body').css('overflow', 'hidden');
            jQuery('body').append('<div class="loading" style="display: flex; width: 100vw; height: 100vh; position: absolute; left: 0; top: 0; justify-content: center; align-items: center;z-index: 999; background: rgba(255,255,255,.6);"><div style="background: #eee; padding: 20px; border-radius: 20px; width: 200px; height: 200px; display: flex; justify-content: center; align-items: center; flex-direction: column; z-index: 999;"><div>Söker efter tid</div><div class="loader-animation">.</div><a href="#" class="cancel-search">Avbryt</a></div></div>');
            loaderAnimation();
        }
    }

    function captcha() {
        if (jQuery('.mtcaptcha').length) {
            playSound('light_bulb_breaking');
            localStorage.removeItem('TimeSearch');
            localStorage.removeItem('responseText');
            setTimeout(function () {
                location.href = location.href;
            }, 1000);
        }
    }

    function loaderAnimation() {
        jQuery('.loader-animation').html('.');
        setTimeout(function () {
            jQuery('.loader-animation').html('..');
        }, 250);
        setTimeout(function () {
            jQuery('.loader-animation').html('...');
        }, 500);
        setTimeout(function () {
            loaderAnimation();
        }, 750);
    }

})();

const express = require('express');
const { body, validationResult } = require('express-validator');
const fetch = require('node-fetch');
const mongoDatabase = require('../utils/mongoDatabase');
const authUtils = require('../utils/auth');
const verificationService = require('../utils/verification');
const {
    checkBruteForce,
    recordFailedAttempt,
    resetFailedAttempts,
    SecurityLogger,
    validateInput
} = require('../middleware/AuthMiddleware');

const router = express.Router();

// Assisted using common GitHub development utilities - Enhanced auth routes with OWASP security

// Middleware pentru validarea input-urilor pe toate rutele auth
router.use(validateInput);

/**
 * POST /api/auth/login 
 * Login enhanced cu OWASP security și role separation
 * OWASP 4.4.3 - Brute force protection
 * OWASP 4.5.3 - Role-based redirection
 */
router.post('/login', [
    body('email').isEmail().normalizeEmail().withMessage('Email invalid'),
    body('password').isLength({ min: 8 }).withMessage('Parolă trebuie să aibă minim 8 caractere')
], async (req, res) => {
    try {
        // Validare errori express-validator
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            SecurityLogger.logAuthAttempt(req.body.email || 'unknown', false, req.ip, req.get('user-agent'));
            return res.status(400).json({
                success: false,
                errors: errors.array().map(err => err.msg)
            });
        }

        const { email, password, rememberMe } = req.body;

        // OWASP 4.4.3 - Verifică protecția împotriva brute force
        const bruteForceCheck = checkBruteForce(email, req.ip);
        if (bruteForceCheck.blocked) {
            SecurityLogger.logSuspiciousActivity(email, 'BRUTE_FORCE_BLOCKED', {
                ip: req.ip,
                remainingTime: bruteForceCheck.remainingTime
            });

            return res.status(429).json({
                success: false,
                error: bruteForceCheck.message,
                lockoutDuration: bruteForceCheck.remainingTime,
                retryAfter: bruteForceCheck.remainingTime
            });
        }

        // Caută utilizatorul în database
        const user = await mongoDatabase.getUserByEmail(email);

        if (!user) {
            recordFailedAttempt(email, req.ip);
            SecurityLogger.logAuthAttempt(email, false, req.ip, req.get('user-agent'));
            return res.status(401).json({
                success: false,
                error: 'Email sau parolă incorectă.'
            });
        }

        // Verifică parola
        const isPasswordValid = await authUtils.verifyPassword(password, user.password);

        if (!isPasswordValid) {
            recordFailedAttempt(email, req.ip);
            SecurityLogger.logAuthAttempt(email, false, req.ip, req.get('user-agent'));
            return res.status(401).json({
                success: false,
                error: 'Email sau parolă incorectă.'
            });
        }

        // Verifică dacă contul este verificat
        if (!user.isVerified) {
            SecurityLogger.logAuthAttempt(email, false, req.ip, req.get('user-agent'));
            return res.status(403).json({
                success: false,
                error: 'Contul nu este verificat. Verifică email-ul sau SMS-ul.',
                requiresVerification: true
            });
        }

        // Reset failed attempts după login reușit
        resetFailedAttempts(email, req.ip);

        // Creează sesiune în baza de date
        const sessionResult = database.createSession(user.id, {
            ipAddress: req.ip,
            userAgent: req.get('user-agent')
        });

        if (!sessionResult.success) {
            console.error('Eroare la crearea sesiunii:', sessionResult.message);
            return res.status(500).json({
                success: false,
                error: 'Eroare internă la autentificare.'
            });
        }

        // Setează cookie HttpOnly cu session_id
        res.cookie('session_id', sessionResult.sessionId, {
            httpOnly: true,
            secure: process.env.NODE_ENV === 'production',
            sameSite: 'strict',
            maxAge: 24 * 60 * 60 * 1000 // 24 ore
        });

        // Set remember me cookie dacă este cerut (refresh token)
        if (rememberMe) {
            const refreshToken = require('crypto').randomUUID();
            // Actualizează sesiunea cu refresh token
            const data = database.readSessions();
            const sessionIndex = data.sessions.findIndex(s => s.id === sessionResult.sessionId);
            if (sessionIndex !== -1) {
                data.sessions[sessionIndex].refreshToken = refreshToken;
                data.sessions[sessionIndex].expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(); // 30 zile
                database.writeSessions(data);
            }

            res.cookie('refresh_token', refreshToken, {
                httpOnly: true,
                secure: process.env.NODE_ENV === 'production',
                sameSite: 'strict',
                maxAge: 30 * 24 * 60 * 60 * 1000 // 30 zile
            });
        }

        // OWASP 4.5.3 - Role-based redirection
        let redirectUrl;
        let accessLevel;

        if (user.role === 'admin') {
            redirectUrl = '/admin/cpanel';
            accessLevel = 'Acces complet CPanel administrativ';
        } else {
            redirectUrl = '/client/schedule-menu';
            accessLevel = 'Acces la meniul personal de programări';
        }

        SecurityLogger.logAuthAttempt(email, true, req.ip, req.get('user-agent'));
        SecurityLogger.logRoleAccess(user.id, user.role, '/login', true, req.ip);

        res.json({
            success: true,
            message: `Autentificare reușită! ${accessLevel}`,
            user: {
                id: user.id,
                firstName: user.firstName,
                lastName: user.lastName,
                email: user.email,
                role: user.role || 'client'
            },
            redirectTo: redirectUrl,
            accessLevel,
            permissions: user.role === 'admin' ? [
                'manage_users',
                'view_all_schedules',
                'system_settings',
                'cpanel_access',
                'security_logs'
            ] : [
                'view_own_schedule',
                'add_schedule',
                'edit_own_profile',
                'view_own_notifications'
            ]
        });

    } catch (error) {
        console.error('Eroare login:', error);
        SecurityLogger.logSuspiciousActivity(req.body?.email || 'unknown', 'LOGIN_ERROR', {
            error: error.message,
            ip: req.ip
        });

        res.status(500).json({
            success: false,
            error: 'Eroare internă de server.'
        });
    }
});

/**
 * GET /api/auth/session
 * Verifică sesiunea curentă și returnează datele utilizatorului
 */
router.get('/session', async (req, res) => {
    try {
        const sessionId = req.cookies.session_id;

        if (!sessionId) {
            return res.status(401).json({
                success: false,
                authenticated: false,
                error: 'Nicio sesiune activă'
            });
        }

        // Găsește sesiunea în baza de date
        const session = database.findSessionById(sessionId);

        if (!session) {
            // Șterge cookie-ul invalid
            res.clearCookie('session_id');
            return res.status(401).json({
                success: false,
                authenticated: false,
                error: 'Sesiune invalidă'
            });
        }

        // Verifică dacă sesiunea a expirat
        if (new Date(session.expiresAt) <= new Date()) {
            // Dezactivează sesiunea expirată
            database.deactivateSession(sessionId);
            res.clearCookie('session_id');
            return res.status(401).json({
                success: false,
                authenticated: false,
                error: 'Sesiune expirată'
            });
        }

        // Actualizează activitatea sesiunii
        database.updateSessionActivity(sessionId);

        // Găsește utilizatorul
        const user = database.findUserById(session.userId);

        if (!user || !user.isActive) {
            // Dezactivează sesiunea pentru utilizator invalid
            database.deactivateSession(sessionId);
            res.clearCookie('session_id');
            return res.status(401).json({
                success: false,
                authenticated: false,
                error: 'Utilizator invalid'
            });
        }

        // Returnează datele utilizatorului
        res.json({
            success: true,
            authenticated: true,
            user: {
                id: user.id,
                firstName: user.firstName,
                lastName: user.lastName,
                email: user.email,
                role: user.role || 'client'
            },
            permissions: user.role === 'admin' ? [
                'manage_users',
                'view_all_schedules',
                'system_settings',
                'cpanel_access',
                'security_logs'
            ] : [
                'view_own_schedule',
                'add_schedule',
                'edit_own_profile',
                'view_own_notifications'
            ]
        });

    } catch (error) {
